import unittest

class TestExtractEmails(unittest.TestCase):

    def test_simple_email(self):
        self.assertEqual(extract_emails("john.doe@example.com"), ["john.doe@example.com"])

    def test_embedded_email(self):
        self.assertEqual(extract_emails("Contact me at john.doe@example.com"), ["john.doe@example.com"])

    def test_multiple_emails(self):
        self.assertEqual(extract_emails("john.doe@example.com and info@example.com"), ["john.doe@example.com", "info@example.com"])

    def test_punctuation(self):
        self.assertEqual(extract_emails("Email us at john.doe@example.com!"), ["john.doe@example.com"])

    def test_non_alphanumeric(self):
        self.assertEqual(extract_emails("john$doe@example.com"), ["john$doe@example.com"])

    def test_no_email(self):
        self.assertEqual(extract_emails("No email addresses here"), [])

    def test_duplicates(self):
        self.assertEqual(extract_emails("john.doe@example.com and john.doe@example.com"), ["john.doe@example.com"])

if __name__ == '__main__':
    unittest.main()
```

