```python
import unittest

def remove_vowels_and_sort_by_frequency(s):
    # Remove vowels
    s = ''.join(c for c in s if c.lower() not in 'aeiou')

    # Count character frequencies
    freq = {}
    for char in s:
        if char not in freq:
            freq[char] = 0
        freq[char] += 1

    # Sort by frequency and alphabetically for ties
    sorted_freq = sorted(freq.items(), key=lambda x: (-x[1], x[0]))

    # Combine sorted characters
    result = ''.join(char * freq for char, freq in sorted_freq)

    return result

class TestRemoveVowelsAndSortByFrequency(unittest.TestCase):
    def test_no_vowels(self):
        self.assertEqual(remove_vowels_and_sort_by_frequency("Hello World"), "llWrHd")

    def test_all_vowels(self):
        self.assertEqual(remove_vowels_and_sort_by_frequency("AEIOUaeiou"), "")

    def test_mixed_case(self):
        self.assertEqual(remove_vowels_and_sort_by_frequency("aBcDeFgHiJ"), "bgdf")

    def test_empty_string(self):
        self.assertEqual(remove_vowels_and_sort_by_frequency(""), "")

if __name__ == "__main__":
    unittest.main()
```

This solution first removes vowels from the input string, then counts character frequencies using a dictionary. It sorts the items in the dictionary by frequency (in descending order) and alphabetically (for ties) using the `sorted` function with a custom key. Finally, it combines the sorted characters to form the result.

The unit tests cover cases with no vowels, all vowels, mixed cases, and an empty string.

