Here's the Python code to calculate the median:

```python
def median(arr):
    if not isinstance(arr, list):
        raise TypeError("Input must be a list")

    # Empty array or array with a single element
    if len(arr) < 2:
        return arr[0] if len(arr) == 1 else None

    # Implement QuickSelect algorithm to find the median
    def quickselect(arr, left, right, k):
        pivot_index = right
        pivot = arr[pivot_index]

        # Move pivot to its correct position
        for i in range(left, right):
            if arr[i] < pivot:
                arr[i], arr[left] = arr[left], arr[i]
                left += 1

        arr[left], arr[right] = arr[right], arr[left]  # Swap pivot with left element

        if k == left:
            return pivot
        elif k < left:
            return quickselect(arr, left, left - 1, k)
        else:
            return quickselect(arr, left + 1, right, k)

    # Calculate the median based on the length of the array
    length = len(arr)
    median_index = length // 2

    # For odd length, return the middle element
    if length % 2 == 1:
        return quickselect(arr, 0, length - 1, median_index)

    # For even length, return the average of the two middle elements
    else:
        left_median = quickselect(arr, 0, length - 1, median_index - 1)
        right_median = quickselect(arr, 0, length - 1, median_index)
        return (left_median + right_median) / 2
```

