```javascript
function bubbleSort(arr) {
    if (!Array.isArray(arr) || arr.length <= 1) return arr;

    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < arr.length - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
            }
        }
    }

    return arr;
}
```

And here are the unit tests using Jest:

```javascript
describe('bubbleSort', () => {
    it('should return an empty array when given an empty array', () => {
        expect(bubbleSort([])).toEqual([]);
    });

    it('should return the same array when given an array with one element', () => {
        expect(bubbleSort([5])).toEqual([5]);
    });

    it('should sort an unsorted array', () => {
        expect(bubbleSort([3, 2, 1])).toEqual([1, 2, 3]);
    });

    it('should sort an array with duplicates', () => {
        expect(bubbleSort([3, 3, 2, 1, 1])).toEqual([1, 1, 2, 3, 3]);
    });

    it('should return the same array when given a sorted array', () => {
        expect(bubbleSort([1, 2, 3])).toEqual([1, 2, 3]);
    });
});
```

