def is_prime(num, base=2, k=5):
    if num < 2:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0:
        return False

    r, power = num - 1, 0
    while r % 2 == 0:
        r, power = r // 2, power + 1

    for _ in range(k):
        candidate = pow(base, r, num)
        if candidate == 1 or candidate == num - 1:
            continue
        for _ in range(power - 1):
            candidate = (candidate * candidate) % num
            if candidate == num - 1:
                break
        else:
            return False

    return True


def generate_primes(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0:
        return []

    primes = [2]
    p = 3
    while len(primes) < n:
        if is_prime(p):
            primes.append(p)
        p += 2

        # Optimization: skip even numbers after checking 2
        if p // 2 in primes:
            while p % 3 == 0:
                p += 2

    return primes
```

