def adaptive_merge_sort(lst):
    if len(lst) <= 1:
        return lst

    mid = len(lst) // 2
    left = lst[:mid]
    right = lst[mid:]

    left = adaptive_merge_sort(left)
    right = adaptive_merge_sort(right)

    return adaptive_merge(left, right)

def adaptive_merge(left, right):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            if i+1 < len(left) and left[i] == left[i+1]:
                i += 1
            else:
                i += 1
        else:
            result.append(right[j])
            if j+1 < len(right) and right[j] == right[j+1]:
                j += 1
            else:
                j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return result

