```javascript
function swapElements(arr, i, j) {
  if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
    throw new Error("Indices are out of bounds");
  }

  if (i === j) {
    return arr.slice();
  }

  const result = arr.slice();
  const temp = result[i];

  function swap(item, index) {
    if (Array.isArray(item)) {
      if (index === i) {
        result[index] = item[j];
      } else if (index === j) {
        result[index] = item[i];
      }
      item.forEach((subItem, subIndex) => swap(subItem, subIndex));
    } else {
      if (index === i) {
        result[index] = result[j];
      } else if (index === j) {
        result[index] = temp;
      }
    }
  }

  swap(result, i);
  swap(result, j);

  return result;
}
```

