  if (!list.length) return -1;

  for (let i = list.length - 1; i >= 0; i--) {
    if (Array.isArray(list[i]) && Array.isArray(target)) {
      const result = linearSearch(list[i], target);
      if (result !== -1) return i;
    } else if (list[i] === target) {
      return i;
    }
  }

  return -1;
}
