```python
class Inventory:
    def __init__(self):
        self.inventory = {}

    def add_item(self, name, quantity, price, nutritional_info):
        if name in self.inventory:
            raise ValueError("Item already exists in inventory")

        self.inventory[name] = {
            "name": name,
            "quantity": quantity,
            "price": price,
            "nutritional_info": nutritional_info
        }

    def remove_item(self, name):
        if name not in self.inventory:
            raise KeyError("Item not found in inventory")

        del self.inventory[name]

    def update_quantity(self, name, new_quantity):
        if name not in self.inventory:
            raise KeyError("Item not found in inventory")

        self.inventory[name]["quantity"] = new_quantity

    def update_price(self, name, new_price):
        if name not in self.inventory:
            raise KeyError("Item not found in inventory")

        self.inventory[name]["price"] = new_price

    def get_nutritional_info(self, name):
        if name not in self.inventory:
            raise KeyError("Item not found in inventory")

        return self.inventory[name]["nutritional_info"]

# Example usage:
inventory = Inventory()

nutritional_info = {
    "calories": 100,
    "carbohydrates": 20.5,
    "vitamins": ["A", "C", "D"]
}

inventory.add_item("apple", 10, 0.5, nutritional_info)
inventory.update_quantity("apple", 8)
inventory.update_price("apple", 0.6)
print(inventory.get_nutritional_info("apple"))
inventory.remove_item("apple")
```

