```javascript
function validateJson(jsonData) {
  const schema = {
    type: "object",
    properties: {
      name: { type: "string" },
      age: { type: "integer", minimum: 1 },
      address: {
        type: "object",
        properties: {
          street: { type: "string" },
          city: { type: "string" },
          state: { type: "string" },
          country: { type: "string" },
        },
        required: ["street", "city", "state", "country"],
      },
      contact: {
        type: "object",
        properties: {
          email: { type: "string", format: "email" },
          phone: {
            type: "string",
            pattern: "^\\+\\d \\d{3}-\\d{3}-\\d{4}$",
          },
        },
        required: ["email", "phone"],
      },
      hobbies: {
        type: "array",
        items: { type: "string" },
      },
      languages: {
        type: "object",
        properties: {
          english: { type: "boolean" },
          spanish: { type: "boolean" },
          french: { type: "boolean" },
        },
        required: ["english", "spanish", "french"],
      },
      education: {
        type: "object",
        properties: {
          degree: { type: "string" },
          major: { type: "string" },
          university: { type: "string" },
        },
        required: ["degree", "major", "university"],
      },
      experience: {
        type: "array",
        items: {
          type: "object",
          properties: {
            company: { type: "string" },
            position: { type: "string" },
            years: { type: "integer", minimum: 1 },
          },
          required: ["company", "position", "years"],
        },
      },
    },
    required: [
      "name",
      "age",
      "address",
      "contact",
      "hobbies",
      "languages",
      "education",
      "experience",
    ],
  };

  const ajv = new Ajv();
  const validate = ajv.compile(schema);
  const valid = validate(jsonData);

  if (!valid) {
    const errors = validate.errors.map((error) => error.message);
    throw new Error("Validation error(s): " + errors.join(", "));
  }

  // Format the JSON data
  const formattedJsonData = JSON.stringify(jsonData, null, 2);

  return formattedJsonData;
}

// Example usage
