import math

def validate_integer(n, name):
    if not isinstance(n, int):
        raise TypeError(f"{name} must be an integer")
    if n != int(n):
        raise ValueError(f"{name} must be an integer")
    if n < 0:
        raise ValueError(f"{name} cannot be negative")

def find_hcf_bitwise(a: int, b: int) -> int:
    """
    Find the highest common factor (HCF) of two given numbers using bitwise operators.

    :param a: The first number.
    :param b: The second number.
    :return: The HCF of the two numbers.
    """
    validate_integer(a, "a")
    validate_integer(b, "b")

    # Handle edge cases where one or both inputs are zero
    if a == 0 or b == 0:
        return math.gcd(a, b)

    # Ensure a is the smaller number
    if a > b:
        a, b = b, a

    # Bitwise operations to find HCF
    while (a & b) != 0:
        a = a & b
        if a > b:
            b = a & b
        else:
            a = a & b

    return a


