import re

def alternate_case(s):
    result = []
    for c in s:
        if result and result[-1].isupper() == c.isupper():
            continue
        result.append(c)
    return ''.join(result)

def count_vowels(s):
    return sum(1 for c in s if c.lower() in 'aeiou')

def valid_text(s):
    if len(s) % 3 != 0:
        return False
    if not re.fullmatch(r'[A-Za-z]*', s):
        return False
    if not all(s[i] != s[i+1] for i in range(0, len(s), 2)):
        return False
    return True

def remove_symbols(s):
    return ''.join(c for c in s if c.isalnum())

def get_valid_text(s):
    s = remove_symbols(s)
    if not s:
        return ''
    s = alternate_case(s)
    valid_strings = [x for x in (s[i:j] for i in range(len(s)) for j in range(i+3, len(s)+3)) if valid_text(x)]
    if not valid_strings:
        return ''
    max_vowels = max(valid_strings, key=count_vowels)
    return min(x for x in valid_strings if count_vowels(x) == count_vowels(max_vowels), key=len)

# Test cases
