```python
from typing import Set

def expand_around_center(s: str, left: int, right: int) -> Set[str]:
    palindromes = set()
    while left >= 0 and right < len(s) and s[left] == s[right]:
        palindromes.add(s[left:right+1])
        left -= 1
        right += 1
    return palindromes

def find_palindromes(s: str) -> Set[str]:
    if not isinstance(s, str) or s == "":
        raise TypeError("Input should be a non-empty string")

    palindromes = set()
    for i in range(len(s)):
        palindromes.update(expand_around_center(s, i, i))
        if i+1 < len(s) and s[i] == s[i+1]:
            palindromes.update(expand_around_center(s, i, i+1))

    # Filter out palindromic substrings with only repeating characters
    filtered_palindromes = set()
    for palindrome in palindromes:
        if palindrome == ''.join(set(palindrome)):
            filtered_palindromes.add(palindrome)

    return filtered_palindromes

# Unit tests
import unittest

class TestFindPalindromes(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(find_palindromes(""), set())

    def test_no_palindromes(self):
        self.assertEqual(find_palindromes("abcdefg"), set())

    def test_all_repeating_characters(self):
        self.assertEqual(find_palindromes("aaa"), set())

    def test_simple_palindromes(self):
        self.assertEqual(find_palindromes("racecar"), {"racecar", "r", "a", "c", "ac", "racecar"})

    def test_mixed_palindromes(self):
        self.assertEqual(find_palindromes("level"), {"l", "e", "l", "v", "le", "el"})

if __name__ == "__main__":
    unittest.main()
