from typing import List, Optional

def second_largest_index(numbers: List[int]) -> Optional[int]:
    if len(numbers) < 2 or not all(num > 0 for num in numbers):
        raise ValueError("Input list must contain at least two positive integers")

    first, second = None, None
    for i, num in enumerate(numbers):
        if num > first:
            second, first = first, num
            index = i
        elif num > second and num != first:
            second = num
            index = i

    if second is None:
        raise ValueError("All elements in the list are the same")

    return index
