def merge_lists(list1, list2):
    # Initialize pointers and merged list
    i, j, merged = 0, 0, []

    # Loop until we've processed all elements from both lists
    while i < len(list1) and j < len(list2):
        # If current element in list1 is smaller, add it to the merged list
        if list1[i] < list2[j]:
            if not merged or merged[-1] != list1[i]:
                merged.append(list1[i])
            i += 1
        # If current element in list2 is smaller or equal, add it to the merged list
        elif list2[j] <= list1[i]:
            if not merged or merged[-1] != list2[j]:
                merged.append(list2[j])
            j += 1
        else:
            i += 1

    # Add any remaining elements from list1
    while i < len(list1):
        if not merged or merged[-1] != list1[i]:
            merged.append(list1[i])
        i += 1

    # Add any remaining elements from list2
    while j < len(list2):
        if not merged or merged[-1] != list2[j]:
            merged.append(list2[j])
        j += 1

    return merged

