```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def generate_primes(limit):
    primes = []
    i = 2
    while len(primes) < limit:
        if is_prime(i):
            primes.append(i)
        i += 1
    return primes

def print_zigzag_pattern(rows, cols):
    primes = generate_primes(rows * cols)

    row, col, direction = 0, 0, 1

    for _ in range(rows * cols):
        print(primes[row * cols + col], end=" ")

        if direction == 1:
            if row == 0 or primes[row * cols + col + cols] != primes[row * cols + col + 1]:
                direction = -1
                row += 1
            else:
                col += 1
        else:
            if row == rows - 1 or primes[(row + 1) * cols + col] != primes[row * cols + col + 1]:
                direction = 1
                col += 1
            else:
                row += 1

if __name__ == "__main__":
    print_zigzag_pattern(10, 10)
```

