        return 2023 - self.age if self.age < 100 else 1923 - (self.age - 100)

    def full_address(self):
        return " ".join(self.address.values())

    def add_address(self, address):
        if len(self._addresses) >= 5:
            raise ValueError("Cannot add more than 5 addresses")
        self._addresses.append(self._validate_address(address))

    def remove_address(self, address_id):
        try:
            del self._addresses[address_id]
        except IndexError:
            raise ValueError("Invalid address ID")

    def search_hobby(self, hobby):
        return any(hobby.lower() in h.lower() for h in self.hobbies)

