        print(f"Hobbies: {', '.join(self.hobbies)}")
        print(f"Address: {self.full_address()}")
        print(f"Country: {self.country}")

    @staticmethod
    def _validate_age(age):
        if not isinstance(age, int) or age < 1:
            raise ValueError("Age must be a positive integer")
        return age

