def count_lowercase_letters(string, min_char=ord('c'), max_char=ord('z'), exclusions=frozenset(['a', 'b'])):
    if not isinstance(string, str):
        return 0

    # Base case: empty string
    if not string:
        return 0

    # Check if the first character is within the desired range and not an exclusion
    char = string[0]
    if ord(char) >= min_char and ord(char) <= max_char and char not in exclusions:
        # Include this character in the count
        return 1 + count_lowercase_letters(string[1:], min_char, max_char, exclusions)
    else:
        # Exclude this character from the count
        return count_lowercase_letters(string[1:], min_char, max_char, exclusions)


