class TestCountLowercaseLetters(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(count_lowercase_letters(""), 0)

    def test_special_characters(self):
        self.assertEqual(count_lowercase_letters("!@#$%^&*()"), 0)

    def test_digits(self):
        self.assertEqual(count_lowercase_letters("1234567890"), 0)

    def test_whitespace(self):
        self.assertEqual(count_lowercase_letters("   "), 0)

    def test_lowercase_letters(self):
        self.assertEqual(count_lowercase_letters("abcdefghijklmnopqrstuvwxyz"), 26)

    def test_exclude_a_and_b(self):
        self.assertEqual(count_lowercase_letters("abcdefghijklmnopqrstuvwxyz", min_char=ord('c'), max_char=ord('z'), exclusions=frozenset(['a', 'b'])) , 24)

    def test_long_string(self):
        long_string = "".join(chr(i) for i in range(ord('a'), ord('z')+1)) * 1000
        self.assertEqual(count_lowercase_letters(long_string), 26000)

if __name__ == "__main__":
