def reverse_string(s):
    if not s:
        return ""

    left, right = 0, len(s) - 1
    while left < right:
        # Swap characters at left and right indices without using a temporary variable
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1

    return s

# Unit tests
import unittest

class TestReverseString(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(reverse_string(""), "")

    def test_single_character(self):
        self.assertEqual(reverse_string("a"), "a")

    def test_palindrome(self):
        self.assertEqual(reverse_string("racecar"), "racecar")

    def test_mixed_case(self):
        self.assertEqual(reverse_string("HelloWorld"), "dlroWolleH")

    def test_special_characters(self):
        self.assertEqual(reverse_string("Hi! There, 123"), "321 ,ereH !iH")

    def test_unicode_characters(self):
        self.assertEqual(reverse_string("🐶������ cats 🐱"), "🐱������ cats 🐶")

    def test_leading_trailing_whitespace(self):
        self.assertEqual(reverse_string(" Hello "), " olleH ")

    def test_multiple_consecutive_spaces(self):
        self.assertEqual(reverse_string("Hi   there"), "ereH   iH")

if __name__ == "__main__":
    unittest.main()
