```python
def are_anagrams(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False

    char_freq = [0] * 26

    for char in s1:
        if char.isalpha():
            char_freq[ord(char.lower()) - ord("a")] += 1

    for char in s2:
        if char.isalpha():
            char_freq[ord(char.lower()) - ord("a")] -= 1

    return all(freq == 0 for freq in char_freq)
```

