def extract_text(html: str, tag: str) -> str:
    """Extracts the text of all occurrences of the given tag.

    Args:
        html (str): The HTML string to parse.
        tag (str): The tag to extract the text from.

    Returns:
        str: The text of all occurrences of the given tag.
    """
    if not html or not tag:
        return ""

    text = ""
    depth = 0
    for c in html:
        if c == "<":
            if html[html.index(c) + 1:].startswith(tag):
                if depth == 0:
                    text += html[html.index(c) + len(tag) + 1:-2] if html[html.index(c) + len(tag) + 1:-1].endswith(">") else ""
            depth += c == "<" and html[html.index(c) + 1] != "/"
        elif c == ">" and depth > 0:
            depth -= 1

    return text
```

