def custom_pop(lst, element):
    if not lst:
        raise IndexError("Pop from an empty list")

    try:
        index = lst.index(element)
    except ValueError:
        raise ValueError(f"{element} not found in the list")

    if index == len(lst) - 1:
        lst.pop()
    else:
        for i in range(len(lst) - 1, index, -1):
            lst[i] = lst[i - 1]
        lst.pop()

    return element

# Unit tests
import unittest

class TestCustomPop(unittest.TestCase):
    def test_multiple_occurrences(self):
        lst = [1, 2, 3, 2, 4]
        self.assertEqual(custom_pop(lst, 2), 2)
        self.assertEqual(lst, [1, 3, 2, 4])

    def test_single_occurrence(self):
        lst = [1, 2, 3, 4]
        self.assertEqual(custom_pop(lst, 3), 3)
        self.assertEqual(lst, [1, 2, 4])

    def test_not_found(self):
        lst = [1, 2, 3, 4]
        with self.assertRaises(ValueError):
            custom_pop(lst, 5)

    def test_empty_list(self):
        lst = []
        with self.assertRaises(IndexError):
            custom_pop(lst, 0)

if __name__ == "__main__":
    unittest.main()
