def fahrenheit_to_celsius(temperature):
    try:
        if not isinstance(temperature, (int, float)):
            raise TypeError("Invalid input. Expected a numeric value.")

        if temperature < -459.67:
            raise ValueError("Invalid input. Temperature below -459.67°F is not possible.")

        if temperature > 1000:
            raise ValueError("Invalid input. Temperature above 1000°F is not allowed.")

        if isinstance(temperature, str):
            if "NaN" in temperature:
                raise ValueError("Invalid input. String contains 'NaN'.")
            temp_value = float(temperature.strip("°F"))
        else:
            temp_value = temperature

        celsius = (temp_value - 32) * 5 / 9
        return round(celsius, 2)

    except ValueError as e:
        return str(e)
    except TypeError as e:
        return str(e)
