            try:
                result = self.decimal_context.decimal(a) / self.decimal_context.decimal(b)
            except decimal.DivisionByZero:
                raise Exception("Division by zero is not allowed.")
            return result

    def square_root(self, number):
        if number < 0:
            raise Exception("Square root of a negative number is not defined.")
