            unique_j, counts_j = np.unique(df.iloc[:, j], return_counts=True)

            if len(unique_i) == len(counts_i) and len(unique_j) == len(counts_j):
                result.iloc[i, j] = "one-to-one"
                result.iloc[j, i] = "one-to-one"
