            raise ValueError(f"Invalid JSON format in the file '{file_path}'. Error: {e}")

    return data

def validate_json_schema(data, schema):
    if not isinstance(data, dict):
        raise ValueError("The root element of the JSON data must be an object.")

    if not isinstance(schema, dict) or 'type' not in schema or schema['type'] != 'object':
        raise ValueError("The JSON schema must be an object with a 'type' property set to 'object'.")

    if 'properties' not in schema or not isinstance(schema['properties'], dict):
        raise ValueError("The 'properties' property is missing or not an object in the JSON schema.")

    if 'required' not in schema or not isinstance(schema['required'], list):
        raise ValueError("The 'required' property is missing or not an array in the JSON schema.")

    for required_field in schema['required']:
        if required_field not in data:
            raise ValueError(f"Required field '{required_field}' is missing in the JSON data.")

        if required_field not in schema['properties'] or not isinstance(schema['properties'][required_field], dict):
            raise ValueError(f"Invalid schema definition for the required field '{required_field}'.")

        field_type = schema['properties'][required_field].get('type')

        if field_type is None:
            raise ValueError(f"Invalid schema definition for the required field '{required_field}'.")

        if not isinstance(data[required_field], field_type):
