import wikipedia
from wordcloud import WordCloud
import matplotlib.pyplot as plt

def get_wikipedia_page_text(page_title):
    if not page_title:
        raise ValueError("Page title cannot be empty.")

    try:
        page = wikipedia.page(page_title)
        return page.content
    except wikipedia.exceptions.DisambiguationError as e:
        return f"Error: The page title '{page_title}' is ambiguous. Please specify the page more clearly."
    except wikipedia.exceptions.PageError as e:
        return f"Error: The page title '{page_title}' does not exist."
    except Exception as e:
        return f"Error: An unexpected error occurred while retrieving the page. Error: {str(e)}"

def clean_text(text):
    return " ".join(re.sub(r'\[.*?\]', '', i).strip() for i in text.split("\n"))

def generate_word_cloud(page_title):
    text = get_wikipedia_page_text(page_title)
    if isinstance(text, str) and text.startswith("Error"):
        print(text)
        return None

    text = clean_text(text)
    wordcloud = WordCloud(background_color="white", max_words=100).generate(text)
    plt.imshow(wordcloud, interpolation="bilinear")
    plt.axis("off")
    plt.show()

if __name__ == "__main__":
    page_title = input("Enter the page title: ")
    generate_word_cloud(page_title)
```

The `get_wikipedia_page_text` function validates the input and handles exceptions that may occur while retrieving the Wikipedia page. The `clean_text` function removes any unnecessary formatting or markup from the text. The `generate_word_cloud` function generates the word cloud using the WordCloud library and displays it using matplotlib. The script can be run by providing the page title as input.

