import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse
from django.core.exceptions import ValidationError
from django.core.rate_limit import reject_action, limit

def task_func(data):
    max_requests = 100  # limit to 100 requests per minute
    rate_limit_wait_time = 60  # wait time in seconds if rate limit is exceeded

    allowed_username = 'admin'
    allowed_password_hash = base64.b64encode(hashlib.sha256('password'.encode()).digest()).decode()

    if not limit(max_requests, 'login_attempts'):
        return reject_action('login_attempts')

    try:
        username = data['username']
        password = data['password']

        if not isinstance(username, str) or not username or not all(c.isalnum() for c in username):
            raise ValidationError('Invalid username format')

        if not isinstance(password, str) or not all(c in '+/=0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz' for c in password):
            raise ValidationError('Invalid password format')

        decoded_password = base64.b64decode(password)
        password_hash = hashlib.sha256(decoded_password).digest()
        hashed_password = base64.b64encode(password_hash).decode()

        if username != allowed_username or hashed_password != allowed_password_hash:
            raise ValidationError('Login failed')

        return HttpResponse('Login successful.', status=400)

    except (KeyError, UnicodeDecodeError, binascii.Error, ValueError, ValidationError) as e:
        return HttpResponseBadRequest('Bad Request.')

    except Exception as e:
        return HttpResponse('An error occurred.', status=500)
