import zipfile
import io
from django.http import FileResponse, HttpRequest
from django.conf import settings

def task_func(request, file_paths):
    if not file_paths:
        return HttpResponse('No files provided.', status=400)

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, mode='w') as zf:
        for file_path in file_paths:
            if not settings.DEBUG and not file_path.startswith(settings.MEDIA_URL):
                return HttpResponse('Invalid file path.', status=400)
            if not settings.DEBUG and not settings.BASE_DIR.join(file_path).exists():
                return HttpResponse('File not found.', status=404)

            if file_path.startswith(settings.MEDIA_URL):
                file_path = file_path.replace(settings.MEDIA_URL, '')
            file_path = settings.BASE_DIR.join(file_path)

            zip_filename = file_path.name
            zf.writestr(zip_filename, file_path.read_text())

    zip_buffer.seek(0)
    content_type = 'application/zip'
    content_disposition = f'attachment; filename="files.zip"'
    response = FileResponse(zip_buffer, as_attachment=True, content_type=content_type)
    response['Content-Disposition'] = content_disposition
    return response
```

