```python
from flask import Flask, make_response
from flask_restful import Resource, Api
import requests
import json

def task_func(api_url, template_folder):
    app = Flask(template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return make_response(json.dumps(response.json()), response.status_code)
            except requests.exceptions.RequestException as err:
                return make_response(json.dumps({"error": str(err)}), 500)

    api.add_resource(ExternalAPIResource, "/external_api")
    return app
```

