import json
import urllib.request
import urllib.parse
import gzip
import os

def task_func(url_str, file_path):
    # Validate URL
    try:
        parsed_url = urllib.parse.urlparse(url_str)
    except ValueError:
        raise ValueError("Invalid URL format")

    # Handle HTTP errors
    try:
        with urllib.request.urlopen(parsed_url) as response:
            if response.status != 200:
                raise Exception(f"HTTP request failed with status {response.status}")
            json_data = response.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        raise Exception(f"HTTP error: {e.code}")
    except Exception as e:
        raise Exception(f"Failed to fetch data from URL: {str(e)}")

    # Validate JSON format
    try:
        json_data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON format: {str(e)}")

    # Validate file path
    if os.path.exists(file_path):
        while os.path.exists(file_path):
            file_path = input("File already exists. Please enter a new file path: ")

    # Compress JSON data
    try:
        with gzip.open(file_path, 'wb') as gzip_file:
            gzip_file.write(json.dumps(json_data).encode())
    except Exception as e:
        raise Exception(f"Failed to write data to file: {str(e)}")

    print(f"JSON data compressed and saved to {file_path}")
