    if df.empty:
        raise ValueError("ValueError: The DataFrame is empty.")

    necessary_columns = {'Title', 'Content'}
    if necessary_columns.symmetric_difference(df.columns):
        raise ValueError("ValueError: The DataFrame does not contain the necessary columns 'Title' and 'Content'.")

    keyword_mask = df['Title'].str.contains(r'\blike\b', case=False) | df['Title'].str.contains(r'\bwhat\b', case=False)
