```python
import pandas as pd
import numpy as np
import folium

def task_func(dic={'Lon': (-180, 180), 'Lat': (-90, 90)}, cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney']):
    if not all(key in dic for key in ('Lon', 'Lat')):
        raise ValueError("Missing 'Lon' or 'Lat' keys in the dictionary.")

    if not all(isinstance(dic[key], tuple) for key in ('Lon', 'Lat')):
        raise ValueError("Values for 'Lon' and 'Lat' keys must be tuples.")

    if not cities:
        return folium.Map(), pd.DataFrame(columns=['City', 'Longitude', 'Latitude'])

    coords = {city: (
        np.random.uniform(*dic['Lon']),
        np.random.uniform(*dic['Lat'])
    ) for city in cities}

    df = pd.DataFrame(coords, index=coords.keys()).reset_index()
    df.columns = ['City', 'Longitude', 'Latitude']

    map_ = folium.Map(location=[df['Latitude'].mean(), df['Longitude'].mean()])
    for _, row in df.iterrows():
        folium.Marker(location=(row['Latitude'], row['Longitude']), popup=row['City']).add_to(map_)

    return map_, df
```

This function checks if the required keys are present in the dictionary and if their values are tuples. If the `cities` list is empty, it returns an empty DataFrame. It generates random coordinates within the specified ranges and creates a DataFrame containing 'City', 'Longitude', and 'Latitude' columns. Finally, it creates a folium map with markers for each city and returns the map and DataFrame as a tuple.

