import numpy as np
from random import choice

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]

def random_data(data_type, length=None):
    if data_type == str:
        return ''.join(choice('abcdefghij') for _ in range(5))
    elif data_type in (int, float):
        return choice(range(10))
    elif data_type in (list, tuple):
        return tuple(choice(range(10)) for _ in range(choice(range(1, 6))))
    elif data_type == dict:
