import re
import requests
import json

def sanitize_input(input_string):
    # Sanitize the input string to prevent injection attacks
    sanitized_string = re.sub('[^a-zA-Z0-9/]', '', input_string)
    return sanitized_string

def task_func(input_string):
    # Extract the API endpoint from the input string
    match = re.search('(https?://[^/]+/[^ ]+)', input_string)
    if not match:
        return {'error': 'Invalid input string. Could not extract API endpoint.'}
    endpoint = match.group(1)

    # Sanitize the endpoint
    endpoint = sanitize_input(endpoint)

    # Send a GET request to the endpoint
    try:
        response = requests.get(endpoint)
    except requests.exceptions.RequestException as e:
        return {'error': f'Error sending GET request to {endpoint}: {e}'}

    # Check if the response status code is 200
    if response.status_code != 200:
        return {'error': f'Error {response.status_code}: Could not retrieve data from {endpoint}'}

    # Process the response data
    try:
        response_data = response.json()
    except json.JSONDecodeError as e:
        return {'error': f'Error decoding JSON data from {endpoint}: {e}'}

    # Return the response data in JSON format
    return {'data': response_data}
