import numpy as np
import itertools
import json

def task_func(data_list, json_file_name="mean_values.json"):
    means = {}
    numeric_vals = (val for val in itertools.chain.from_iterable(data_list) if isinstance(val, (int, float)))
    if not numeric_vals:
        return means
    grouped_vals = itertools.groupby(sorted(numeric_vals, key=type), key=type)
    for _type, vals in grouped_vals:
        if _type is int or _type is float:
            means['Position {}'.format(grouped_vals.index(_type) + 1)] = np.mean(list(vals))
    if json_file_name:
        with open(json_file_name, 'w') as f:
            json.dump(means, f)
    return means
