import collections
import random

# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']

def generate_dict(n_keys, n_values):
    if n_keys > len(LETTERS):
        keys = random.sample(LETTERS, len(LETTERS))
    else:
        keys = random.sample(LETTERS, n_keys)

    value_iter = enumerate(range(1, n_values + 1))
    result = collections.defaultdict(list)

    for key in keys:
        index, value = next(value_iter)
        result[key].append(value)

    return dict(result)


def test_generate_dict():
    assert generate_dict(5, 3) == {'a': [1], 'c': [2], 'e': [3], 'b': [1], 'd': [2]}
    assert generate_dict(10, 5) == {'c': [1, 2], 'e': [3, 4], 'a': [1, 5], 'i': [2, 5], 'h': [3, 5], 'g': [4]}
    assert generate_dict(3, 10) == {'b': [1, 2, 3], 'a': [4], 'j': [5]}


if __name__ == "__main__":
    test_generate_dict()
    print(generate_dict(5, 3))
