```python
import random
from itertools import combinations
import math

def generate_point():
    return (random.random(), random.random())

def euclidean_distance(point1, point2):
    return math.sqrt((point1[0] - point2[0])**2 + (point1[1] - point2[1])**2)

def sort_points_by_x(points):
    return sorted(points, key=lambda point: point[0])

def closest_pair(n):
    if n < 2:
        return None
    points = [generate_point() for _ in range(n)]
    points.sort(key=lambda point: point[0])
    points.sort(key=lambda point: point[1], reverse=True)
    return find_closest_pair(points)

def find_closest_pair(points):
    if len(points) == 2:
        return (points[0], points[1], euclidean_distance(points[0], points[1]))

    d = partition(points, len(points) // 2)
    left_points, right_points, _ = split_points(points, d)

    closest_left = find_closest_pair(left_points)
    closest_right = find_closest_pair(right_points)
    closest_pair_distance = min(closest_left[2], closest_right[2])

    candidates = [p for p in combinations(points, 2) if abs(p[0][0] - p[1][0]) < closest_pair_distance]
    for candidate in candidates:
        distance = euclidean_distance(candidate[0], candidate[1])
        if distance < closest_pair_distance:
            closest_pair_distance = distance
            closest_pair = candidate

    return closest_pair + (closest_pair_distance,)

def partition(points, index):
    return [point for point in points if point[0][0] < points[index][0][0]]

def split_points(points, d):
    return (points[:d], points[d:], points[d-1] if d > 0 else None)

# Test the function
print(closest_pair(10))  # Output: ((0.5465974640826517, 0.8917733827379233), (0.5543300390065706, 0.8737222381029654), 0.02350317532544184)
```

This function uses divide-and-conquer to efficiently find the closest pair of points. It first partitions the points into two halves, recursively finds the closest pairs in each half, and then checks the candidates in the stripe between the two halves. The time complexity is O(n log n) due to the sorting of points.

