import collections
import json
import os

def task_func(directory_path: str) -> dict:
    count_dict = collections.defaultdict(int)
    if not os.path.exists(directory_path) or not os.path.isdir(directory_path):
        raise FileNotFoundError(f"The specified directory '{directory_path}' does not exist.")

    for filename in os.listdir(directory_path):
        if not filename.endswith(".json"):
            continue
        file_path = os.path.join(directory_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r") as file:
                data = json.load(file, object_pairs_hook=collections.OrderedDict)
        except KeyError as e:
            print(f"Warning: JSON decoding error in file '{file_path}'. Ignoring this file.")
            continue
        except json.JSONDecodeError as e:
            print(f"Warning: JSON decoding error in file '{file_path}'. Ignoring this file.")
            continue

        for key, value in data.items():
            count_dict[key] += 1

    return dict(count_dict)

