```python
import re
import os
import shutil
from datetime import datetime

def task_func(directory):
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")

    organized_files = {"directories": {}, "path": directory}

    for item in os.listdir(directory):
        item_path = os.path.join(directory, item)
        if os.path.isfile(item_path):
            match = re.search(r'\[(.*?)\]', item)
            if match:
                subdir_name = match.group(1).strip()
            else:
                subdir_name = None

            if subdir_name:
                subdir_path = os.path.join(directory, subdir_name)
                if subdir_name not in organized_files["directories"]:
                    organized_files["directories"][subdir_name] = []
                    os.makedirs(subdir_path, exist_ok=True)
                organized_files["directories"][subdir_name].append(item)
                shutil.move(item_path, subdir_path)

