```python
import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    # Validate the regex_pattern
    try:
        re.compile(regex_pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    # Check if the directory exists
    directory_path = Path(directory_path)
    if not directory_path.exists():
        raise FileNotFoundError(f"Directory '{directory_path}' not found")

    # Process files in the directory
    matches_dict = {}
    for file_path in glob.glob(str(directory_path) + "/**/*.txt", recursive=True):
        file_name = file_path.name
        matches = set()  # Use a set to store unique matches

        try:
            with open(file_path, 'r') as f:
                for line in f:
                    for match in re.finditer(regex_pattern, line):
                        group_num = 1 if match.group(1) else 0
                        matches.add(match.group(group_num))
        except Exception as e:
            print(f"Error processing file '{file_name}': {e}")

        matches_dict[file_name] = list(matches)

    return matches_dict
