import re
import json
import os

def task_func(file_path: str, regex_pattern=r'\(.+?)|\w') -> dict:
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"The file '{file_path}' does not exist.")

    if not file_path.endswith('.json'):
        raise ValueError(f"The file '{file_path}' is not a JSON file.")

    with open(file_path, 'r') as f:
        try:
            data = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"The file '{file_path}' is not a valid JSON file: {e}")

    matches = []
    for value in data.values():
        if isinstance(value, str):
            matches.extend(re.findall(regex_pattern, value))

    return {os.path.basename(file_path): matches}
