import subprocess
import os
import shutil
from glob import glob
import logging

def task_func(src_folder, dst_folder):
 log_file = "compression_log.txt"
 logging.basicConfig(filename=log_file, level=logging.ERROR)

 if not os.path.exists(src_folder) or not os.path.isdir(src_folder):
 raise ValueError(f"Source folder '{src_folder}' does not exist or is not a folder.")

 if not os.path.exists(dst_folder) or not os.path.isdir(dst_folder):
 raise ValueError(f"Destination folder '{dst_folder}' does not exist or is not a folder.")

 success = True
 failed_files = []

 for file_path in glob(os.path.join(src_folder, "*")):
 if os.path.isfile(file_path):
 try:
 gzip_cmd = ["gzip", "-c", file_path]
 with open(file_path + ".gz", "wb") as outfile:
 subprocess.run(gzip_cmd, check=True, stdout=outfile)
 shutil.move(file_path, dst_folder)
 except Exception as e:
 logging.error(f"Error compressing and moving file {file_path}: {e}")
 success = False
 failed_files.append(file_path)

 return {
 "success": success,
 "message": f"Compression and move operation completed. Check {log_file} for errors.",
 "failed_files": failed_files
 }

