```python
from collections import defaultdict

class MassEditingSystem:
    def __init__(self):
        self.templates = {}
        self.sidebar_actions = {}
        self.model_inheritance = defaultdict(set)

    def create_template(self, name, model):
        if name in self.templates:
            raise ValueError(f"Template name '{name}' already exists.")
        self.templates[name] = {
            "model": model,
            "editing_lines": [],
            "inheritance": self.model_inheritance[model]
        }

    def add_editing_line(self, name, field, new_value):
        if name not in self.templates:
            raise KeyError(f"Template '{name}' does not exist.")
        self.templates[name]["editing_lines"].append({"field": field, "new_value": new_value})

    def create_sidebar_action(self, name):
        if name not in self.templates:
            raise KeyError(f"Template '{name}' does not exist.")
        model = self.templates[name]["model"]
        self.sidebar_actions[name] = model

    def delete_sidebar_action(self, name):
        if name not in self.sidebar_actions:
            raise KeyError(f"Sidebar action '{name}' does not exist.")
        del self.sidebar_actions[name]

    def delete_template(self, name):
        if name not in self.templates:
            raise KeyError(f"Template '{name}' does not exist.")
        for action in list(self.sidebar_actions.keys()):
            if self.sidebar_actions[action] == self.templates[name]["model"]:
                del self.sidebar_actions[action]
        del self.templates[name]

    def copy_template(self, original_name, new_name):
        if original_name not in self.templates:
            raise KeyError(f"Template '{original_name}' does not exist.")
        self.create_template(new_name, self.templates[original_name]["model"])
        self.templates[new_name]["editing_lines"] = self.templates[original_name]["editing_lines"].copy()

    def add_inheritance(self, parent_model, child_model):
        self.model_inheritance[parent_model].add(child_model)

    def get_templates_for_model(self, model):
        templates = []
        for name, template in self.templates.items():
            if template["model"] == model or model in template["inheritance"]:
                templates.append(template)
        return templates
```

