        self.variables[var_name.strip()] = value

    def define_function(self, statement):
        def_parts = statement.split(':')
        func_name = def_parts[0].strip()
        params = def_parts[1].split('(')[1].split(')')[0].split(',')
        body = def_parts[2].strip()

        if any(param.strip() for param in params):
            params = [param.strip() for param in params]
        else:
            params = []

        self.functions[func_name] = lambda scope, params: self.evaluate_expression(body, scope=scope, params=params)

    def evaluate_expression(self, expr, scope=None, params=None):
        if scope is None:
            scope = self.variables

        if params is None:
            params = []

        def repl(match):
            var_name = match.group(1)
            if var_name in scope:
                return str(scope[var_name])
            elif var_name in self.built_in_functions:
                return str(self.built_in_functions[var_name](float(match.group(2))))
            else:
                raise Exception(f"Undefined variable: {var_name}")

        def call_func(func_name, args):
            if func_name in self.functions:
                func = self.functions[func_name]
