            else:
                raise Exception(f"Undefined function: {func_name}")

        pattern = r'(?P<name>[a-zA-Z_]\w*)|(?P<num>\d+(\.\d*)?)|(?P<func>sin|cos|tan|asin|acos|atan)\((?P<arg>\d+(\.\d*)?)\)'

        def repl_func(match):
            func_name = match.group(1)
            args = match.group(2).split(',')
            return call_func(func_name, args)

        expr = re.sub(pattern, repl, expr)
        expr = re.sub(r'\((?P<func>sin|cos|tan|asin|acos|atan)\((?P<arg>\d+(\.\d*)?)\)\)', repl_func, expr)

        try:
            return eval(expr)
        except Exception as e:
            raise Exception(f"Invalid expression: {expr}")

    def start_shell(self):
        print("Welcome to the interactive shell!")
        print("Type 'exit()' to quit.")
        print("Available functions:")
        for name, func in self.functions.items():
            print(f"- {name}")
        print("Available variables:")
        for name, value in self.variables.items():
            print(f"- {name} = {value}")

        while True:
            user_input = input("> ").strip()
            if user_input == 'exit()':
                break
            try:
                result = self.execute(user_input)
                print(result)
            except Exception as e:
                print(f"Error: {e}")

