from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/add', methods=['POST'])
def add():
    return calculate('add')

@app.route('/sub', methods=['POST'])
def sub():
    return calculate('sub')

@app.route('/mul', methods=['POST'])
def mul():
    return calculate('mul')

@app.route('/div', methods=['POST'])
def div():
    return calculate('div')

@app.route('/bitand', methods=['POST'])
def bitand():
    return calculate('bitand')

def calculate(operation):
    data = request.get_json()

    if not all(isinstance(item, int) for item in (data.get('N1'), data.get('N2'))):
        return jsonify({'error': 'Both N1 and N2 must be integers'}), 400

    N1 = data['N1']
    N2 = data['N2']

    if operation == 'div' and N2 == 0:
        return jsonify({'error': 'Division by zero is not allowed'}), 400

    methods = {
        'add': lambda: N1 + N2,
        'sub': lambda: N1 - N2,
        'mul': lambda: N1 * N2,
        'div': lambda: N1 // N2 if N2 else None,
        'bitand': lambda: N1 & N2,
    }

    result = methods[operation]()

    if result is None:
        return jsonify({'error': 'Division by zero is not allowed'}), 400

    return jsonify({operation: result})

if __name__ == '__main__':
    app.run(debug=True)
