from abc import ABC, abstractmethod
from exceptions import BusinessLogicException, UniqueConstraintFailedException, DoesNotExistException, NoAccessException

class InventoryException(Exception):
    pass

class UniqueConstraintFailedException(InventoryException):
    pass

class DoesNotExistException(InventoryException):
    pass

class BusinessLogicException(InventoryException):
    pass

class NoAccessException(InventoryException):
    pass

class InventoryManager(ABC):
    def __init__(self):
        self._inventory = {}

    @abstractmethod
    def check_access(self, user_role):
        if user_role != 'admin':
            raise NoAccessException('User does not have the required role to modify the inventory.')

    @abstractmethod
    def add_item(self, item_id, quantity):
        self.check_access('admin')
        if not isinstance(quantity, int) or quantity < 0:
            raise BusinessLogicException('Quantity must be a non-negative integer.')
        if item_id in self._inventory:
            raise UniqueConstraintFailedException(f'Item with ID {item_id} already exists.')
        self._inventory[item_id] = quantity

    @abstractmethod
    def remove_item(self, item_id):
        self.check_access('admin')
        if item_id not in self._inventory:
            raise DoesNotExistException(f'Item with ID {item_id} does not exist.')
        del self._inventory[item_id]

    @abstractmethod
    def update_quantity(self, item_id, quantity):
        self.check_access('admin')
        if item_id not in self._inventory:
            raise DoesNotExistException(f'Item with ID {item_id} does not exist.')
        if not isinstance(quantity, int) or quantity < 0:
            raise BusinessLogicException('Quantity must be a non-negative integer.')
        self._inventory[item_id] = quantity

    @abstractmethod
    def get_item_quantity(self, item_id):
        if item_id not in self._inventory:
            raise DoesNotExistException(f'Item with ID {item_id} does not exist.')
        return self._inventory[item_id]

    @abstractmethod
    def get_total_items(self):
        return len(self._inventory)
