import unittest

def string_operations(s, operations):
    if not s:
        return [None] * len(operations)

    def slice_op(start, end):
        try:
            return s[start:end]
        except IndexError:
            return ''

    def check_op(sub):
        return sub in s

    def concat_op(str_to_add):
        return s + str_to_add

    def format_op(values):
        try:
            formatted = s.format(*values)
            return formatted
        except ValueError:
            return None

    results = []
    for op, *params in operations:
        if op == 'slice':
            results.append(slice_op(*params))
        elif op == 'check':
            results.append(check_op(params[0]))
        elif op == 'concat':
            results.append(concat_op(params[0]))
        elif op == 'format':
            results.append(format_op(params))
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return results

class TestStringOperations(unittest.TestCase):
    def test_empty_string(self):
        s = ''
        ops = [('slice', 0, 1), ('check', 'a'), ('concat', 'b'), ('format', ())]
        result = string_operations(s, ops)
        self.assertEqual(result, ['', False, 'b', None])

    def test_valid_operations(self):
        s = 'Hello, world!'
        ops = [('slice', 7, 13), ('check', 'world'), ('concat', '!!'), ('format', (1, 2))]
        result = string_operations(s, ops)
        self.assertEqual(result, ['world', True, 'Hello, world!!', 'H2o, w2rld!'])

    def test_invalid_operation(self):
        s = 'Invalid operations'
        ops = [('slice', 0, 1), ('check', 'a'), ('unknown', 'b'), ('format', ())]
        with self.assertRaises(ValueError):
            string_operations(s, ops)

if __name__ == '__main__':
    unittest.main()
