        self.port = int(os.getenv("EMAIL_PORT", 587))
        self.username = os.getenv("EMAIL_USERNAME", "your_email@example.com")
        self.password = os.getenv("EMAIL_PASSWORD", "your_password")
        self.from_email = os.getenv("EMAIL_FROM", "Your Name <your_email@example.com>")

    def send_email(self, recipients, subject, body):
        print(f"Sending email to {recipients} with subject {subject} and body:")
        print(body)

def load_recipients_from_file(file_path):
    with open(file_path, "r") as f:
        recipients = [line.strip() for line in f.readlines()]
    return recipients


if __name__ == "__main__":
    config = EmailConfig()
    recipients_file = "recipients.txt"
    if os.path.isfile(recipients_file):
        recipients = load_recipients_from_file(recipients_file)
    else:
        recipients = ["recipient1@example.com", "recipient2@example.com"]

