```python
import sys
import pygame
import random
import time

# Constants
GRID_SIZE = 20
CELL_SIZE = 20
WIDTH = HEIGHT = GRID_SIZE * CELL_SIZE
FPS = 10

BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
GREEN = (0, 255, 0)

class Grid:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.cells = [[False for _ in range(width)] for _ in range(height)]

    def get_cell(self, x, y):
        return self.cells[y][x]

    def set_cell(self, x, y, value):
        self.cells[y][x] = value

    def count_neighbors(self, x, y):
        count = 0
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                nx, ny = x + i, y + j
                if 0 <= nx < self.width and 0 <= ny < self.height:
                    count += self.get_cell(nx, ny)
        return count

    def update(self):
        new_cells = [[False for _ in range(self.width)] for _ in range(self.height)]
        for y in range(self.height):
            for x in range(self.width):
                neighbors = self.count_neighbors(x, y)
                if self.get_cell(x, y):
                    new_cells[y][x] = neighbors in [2, 3]
                else:
                    new_cells[y][x] = neighbors == 3
        self.cells = new_cells

def draw_grid(screen, grid):
    for y in range(grid.height):
        for x in range(grid.width):
            color = WHITE if grid.get_cell(x, y) else BLACK
            pygame.draw.rect(screen, color, (x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE))

def handle_manual_configuration(grid, mouse_pos):
    x, y = mouse_pos[0] // CELL_SIZE, mouse_pos[1] // CELL_SIZE
    grid.set_cell(x, y, not grid.get_cell(x, y))

def main():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    pygame.display.set_caption("Conway's Game of Life")
    clock = pygame.time.Clock()

    grid = Grid(GRID_SIZE, GRID_SIZE)
    running = True
    manual_configuration = True

    while running:
        screen.fill(BLACK)

        if manual_configuration:
            draw_grid(screen, grid)
            pygame.display.set_caption("Conway's Game of Life - Configure Cells Manually")
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False
                elif event.type == pygame.MOUSEBUTTONDOWN:
                    handle_manual_configuration(grid, pygame.mouse.get_pos())
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_RETURN:
                        manual_configuration = False
                    elif event.key == pygame.K_ESCAPE:
                        running = False
        else:
            grid.update()
            pygame.display.set_caption("Conway's Game of Life - Press ESC to exit")
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    running = False

        pygame.display.flip()
        clock.tick(FPS)

    pygame.quit()
    sys.exit()

if __name__ == "__main__":
    main()
```

