```python
import os
import json
from unittest import TestCase, main

class Response:
    def __init__(self):
        self.success = True
        self.message = ""

class ProjectOpener:
    @staticmethod
    def project_exists(path):
        return os.path.isdir(path) and os.path.exists(os.path.join(path, "project.json"))

    @staticmethod
    def load_project(response, path):
        if not ProjectOpener.project_exists(path):
            response.success = False
            response.message = f"Project '{path}' does not exist."
            return False

        try:
            with open(os.path.join(path, "project.json")) as f:
                project = json.load(f)
        except Exception as e:
            response.success = False
            response.message = f"Failed to load project '{path}': {str(e)}"
            return False

        # Update the response object with project information
        response.project = project
        response.message = f"Project '{path}' loaded successfully."
        return True

    @staticmethod
    def open_project(path, forget=False):
        response = Response()
        if not ProjectOpener.load_project(response, path):
            return response

        # Initialize result paths or any other necessary actions
        ProjectOpener.initialize_results(response, response.project)
        if not forget:
            # Update recent paths or any other persistent state
            pass

        return response

    @staticmethod
    def initialize_results(response, project):
        # Initialize result paths based on the project
        response.results_path = os.path.join(project["path"], "results")
        if not os.path.exists(response.results_path):
            os.makedirs(response.results_path)

class TestProjectOpener(TestCase):
    def test_project_exists(self):
        self.assertTrue(ProjectOpener.project_exists("tests/project_exists"))
        self.assertFalse(ProjectOpener.project_exists("tests/non_existent_project"))

    def test_load_project_success(self):
        response = Response()
        ProjectOpener.load_project(response, "tests/project_exists")
        self.assertTrue(response.success)
        self.assertEqual(response.message, "Project 'tests/project_exists' loaded successfully.")

    def test_load_project_failure_nonexistent(self):
        response = Response()
        ProjectOpener.load_project(response, "tests/non_existent_project")
        self.assertFalse(response.success)
        self.assertEqual(response.message, "Project 'tests/non_existent_project' does not exist.")

    def test_load_project_failure_load(self):
        response = Response()
        ProjectOpener.load_project(response, "tests/project_load_failure")
        self.assertFalse(response.success)
        self.assertTrue("Failed to load project" in response.message)

    def test_open_project_success(self):
        response = ProjectOpener.open_project("tests/project_exists")
        self.assertTrue(response.success)
        self.assertEqual(response.message, "Project 'tests/project_exists' loaded successfully.")

    def test_open_project_failure_nonexistent(self):
        response = ProjectOpener.open_project("tests/non_existent_project")
        self.assertFalse(response.success)
        self.assertEqual(response.message, "Project 'tests/non_existent_project' does not exist.")

    def test_open_project_failure_load(self):
        response = ProjectOpener.open_project("tests/project_load_failure")
        self.assertFalse(response.success)
        self.assertTrue("Failed to load project" in response.message)

if __name__ == "__main__":
    main(verbosity=2)
```

