import os
import requests
from bs4 import BeautifulSoup
import time

def get_html(url):
    response = None
    while response is None:
        try:
            response = requests.get(url)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching HTML: {e}")
            time.sleep(5)  # Wait for 5 seconds before retrying

    return response.text


def parse_tiles(html_content):
    soup = BeautifulSoup(html_content, "html.parser")
    tile_links = []

    for link in soup.find_all("a"):
        if "HGT" in link.get("href"):
            tile_links.append(link.get("href"))

    return tile_links


def download_file(url, output_dir, file_name):
    local_filename = os.path.join(output_dir, file_name)
    response = None

    while response is None:
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            print(f"Error downloading file: {e}")
            time.sleep(5)  # Wait for 5 seconds before retrying

    with open(local_filename, "wb") as f:
        for chunk in response.iter_content(1024):
            f.write(chunk)

    print(f"Downloaded {file_name} to {output_dir}")


def main():
    base_url = "https://srtm.csi.cgiar.org/srtmdata/"
    output_dir = input("Enter the output directory: ")
    data_type = input("Enter the data type (GeoTIFF or ASCII): ").lower()

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    html_content = get_html(base_url)
    tile_links = parse_tiles(html_content)

    specific_tile = input("Enter a specific tile to download (or leave blank to download all): ").strip()

    if specific_tile:
        tile_link = next((l for l in tile_links if specific_tile in l), None)

        if tile_link is None:
            print(f"No matching tile found for {specific_tile}")
        else:
            file_name = os.path.basename(tile_link)
            download_file(tile_link, output_dir, file_name)
    else:
        for tile_link in tile_links:
            file_name = os.path.basename(tile_link)

            if data_type in file_name.lower():
                print(f"Downloading {file_name}...")
                download_file(tile_link, output_dir, file_name)
            else:
                print(f"Skipping {file_name} (not the specified data type)")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nDownload interrupted by user. Exiting...")
```

This script automates the process of downloading SRTM elevation data tiles from the CGIAR-CSI SRTM data repository. Users can specify the type of data (GeoTIFF or ASCII), the output directory to store the downloaded tiles, and optionally a specific tile to download. If no specific tile is provided, the script will download all available tiles of the specified type.

The script uses the `requests` library for HTTP requests and BeautifulSoup for parsing HTML. It handles interruptions gracefully, allowing users to cancel the download process with a keyboard interrupt (Ctrl+C). It also handles any request exceptions by retrying the download and provides informative messages about the download progress and any issues encountered.

