        {"contact": "Contact 4", "date": datetime.date(2022, 12, 5), "type": "Follow-up"},
    ],
}

def authenticate(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if "user" not in st.session_state:
            st.sidebar.title("Authentication")
            username = st.sidebar.text_input("Username")
            password = st.sidebar.text_input("Password", type="password")

            if st.sidebar.button("Login"):
                if username in users and users[username]["password"] == password:
                    st.session_state.user = username
                else:
                    st.sidebar.error("Invalid credentials")

            return None if st.session_state.user is None else func(*args, **kwargs)
        else:
            return func(*args, **kwargs)

    return wrapper

@authenticate
def overview_page():
    st.title("Overview")
    st.write(f"Welcome, {users[st.session_state.user]['name']}!")
    st.write("Summary of interactions and activities:")

@authenticate
def contact_pages():
    st.title("Contact Pages")
    st.write("Manage your contacts here.")

    if st.button("Add Contact"):
        st.write("Adding a new contact...")

    for idx, contact in enumerate(contacts[st.session_state.user]):
        st.write(f"Contact {idx + 1}:")
        st.write(f"- Name: {contact['name']}")
        st.write(f"- Email: {contact['email']}")
        st.write(f"- Phone: {contact['phone']}")

        if st.button("Edit Contact"):
            st.write("Editing the contact...")

        if st.button("Delete Contact"):
            st.write("Deleting the contact...")

@authenticate
def account_page():
