import re
from datetime import datetime, time, timedelta
from typing import Dict, Any

class NoDevice(Exception):
    pass

def unix_timestamp_to_human_readable(unix_timestamp: str, separator: str = ':') -> str:
    """
    Convert a Unix timestamp string to a human-readable time string with a custom separator.

    :param unix_timestamp: The Unix timestamp string to convert.
    :param separator: The separator to use in the human-readable time string.
    :return: The human-readable time string.
    """
    if not unix_timestamp or not separator:
        return ''

    try:
        epoch = datetime.fromtimestamp(int(unix_timestamp))
        return epoch.strftime(f'%H{separator}%M{separator}%S')
    except ValueError as e:
        print(f'Error converting Unix timestamp to human-readable time: {e}')
        return ''

def human_readable_to_unix_timestamp(human_readable_time: str, separator: str = ':') -> int:
    """
    Convert a human-readable time string with a custom separator to a Unix epoch timestamp.

    :param human_readable_time: The human-readable time string to convert.
    :param separator: The separator used in the human-readable time string.
    :return: The Unix epoch timestamp.
    """
    if not human_readable_time or not separator:
        return 0

    try:
        pattern = r'^(0?[0-9]|1[0-9]|2[0-3]){separator}(0?[0-9]|1[0-9]|2[0-9]){separator}(0?[0-9]|1[0-9]|2[0-9])$'
        if not re.match(pattern.format(separator=separator), human_readable_time):
            return 0

        time_parts = tuple(map(int, human_readable_time.split(separator)))
        return int(datetime(1970, 1, 1, *time_parts).timestamp())
    except ValueError as e:
        print(f'Error converting human-readable time to Unix timestamp: {e}')
        return 0

def get_current_day_timestamps() -> tuple[int, int]:
    """
    Calculate the Unix timestamps for the start and end of the current day (00:00:00 to 23:59:59).

    :return: A tuple containing the Unix timestamp for the start of the day and the Unix timestamp for the end of the day.
    """
    now = datetime.now()
    start_of_day = datetime.combine(now.date(), time.min)
    end_of_day = datetime.combine(now.date(), time.max)

    return int(start_of_day.timestamp()), int(end_of_day.timestamp())

def cleanup_ids(raw_data: dict) -> dict:
    """
    Clean up device and module IDs in the raw data by removing any superfluous spaces.

    :param raw_data: The raw data containing device and module IDs.
    :return: The cleaned-up raw data.
    """
    for key, value in list(raw_data.items()):
        if isinstance(value, dict):
            raw_data[key] = cleanup_ids(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    item = cleanup_ids(item)
            raw_data[key] = value
        elif isinstance(value, str):
            raw_data[key] = value.strip()

    return raw_data

def extract_data(server_response: str) -> Dict[str, Any]:
    """
    Extract raw data from a server response, handling different tags and potential errors, and return a dictionary with the relevant data and any errors.

    :param server_response: The server response to extract data from.
    :return: A dictionary containing the extracted data and any errors.
    """
    raw_data = {}
    errors = []

    try:
        response_parts = server_response.split('<')
        for part in response_parts:
            if 'device' in part:
                device_data = part.split('>')[1].split('</')[0]
                device_id, data = device_data.split(' ', 1)
                raw_data[device_id] = {}
                for item in data.split(' '):
                    if item:
                        key, value = item.split(':')
                        raw_data[device_id][key] = value

            elif 'module' in part:
                module_data = part.split('>')[1].split('</')[0]
                module_id, data = module_data.split(' ', 1)
                if device_id not in raw_data:
                    errors.append(f'Missing device data for module: {module_data}')
                    continue
                raw_data[device_id]['module'] = {}
                for item in data.split(' '):
                    if item:
                        key, value = item.split(':')
                        raw_data[device_id]['module'][key] = value

            elif 'error' in part:
                error_data = part.split('>')[1].split('</')[0]
                errors.append(error_data)

    except Exception as e:
        print(f'Error extracting data from server response: {e}')
        errors.append(str(e))

    if not raw_data:
        if errors:
            raise NoDevice(f'No device data available or errors: {", ".join(errors)}')
        else:
            raise NoDevice('No device data available')

    raw_data = cleanup_ids(raw_data)

    return raw_data
