def find_vulnerable_computers(n, connections):
    if n < 1:
        return []

    # Validate connections
    for connection in connections:
        if not isinstance(connection, tuple) or len(connection) != 2 or not all(1 <= i <= n for i in connection):
            raise ValueError("Invalid connection format")

    graph = {i: set() for connection in connections for i in connection}
    for a, b in connections:
        graph[a].add(b)

    def bfs_hackable_count(start):
        hacked = set()
        queue = [start]

        while queue:
            computer = queue.pop(0)
            if computer not in hacked:
                hacked.add(computer)
                queue.extend(neighbor for neighbor in graph[computer] if neighbor not in hacked)

        return len(hacked)

    max_hackable_count = 0
    vulnerable_computers = []

    for computer in range(1, n+1):
        hackable_count = bfs_hackable_count(computer)
        if hackable_count > max_hackable_count:
            max_hackable_count = hackable_count
            vulnerable_computers = [computer]
        elif hackable_count == max_hackable_count:
            vulnerable_computers.append(computer)

    return vulnerable_computers


if __name__ == "__main__":
    n = int(input("Enter the number of computers: "))
    m = int(input("Enter the number of connections: "))
    connections = [tuple(map(int, input(f"Enter connection {i+1}: ").split())) for i in range(m)]

    vulnerable_computers = find_vulnerable_computers(n, connections)
    print(f"The most vulnerable computers are: {vulnerable_computers}")
