```python
import sys

def read_file(file_path):
    try:
        with open(file_path, 'r') as file:
            sentences = [line.strip() for line in file.readlines() if line.strip()]
        return sentences
    except FileNotFoundError:
        print(f"Error: The file '{file_path}' does not exist.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Cannot read the file '{file_path}' due to insufficient permissions.")
        sys.exit(1)

def process_data(sentences):
    word_counts = {}
    total_sentences = len(sentences)

    for sentence in sentences:
        words = sentence.split()
        length = len(words)

        if length not in word_counts:
            word_counts[length] = {'count': 0, 'cumulative_percentage': 0}

        word_counts[length]['count'] += 1

        cumulative_count = sum(value['count'] for value in word_counts.values())
        word_counts[length]['cumulative_percentage'] = cumulative_count / total_sentences

    return word_counts

def print_output(word_counts):
    print("Length Count Cumulative_Percentage")
    for length, data in word_counts.items():
        print(f"{length} {data['count']} {data['cumulative_percentage']:.2f}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python sentence_distribution.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    sentences = read_file(file_path)
    word_counts = process_data(sentences)
    print_output(word_counts)
```

