import jieba

def load_dataset(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            data = [line.strip().split('\t') for line in file.readlines()]
        return data
    except FileNotFoundError:
        print(f"The file '{file_path}' does not exist.")
        return []
    except PermissionError:
        print(f"Unable to read the file '{file_path}'.")
        return []
    except Exception as e:
        print(f"Error loading dataset: {e}")
        return []

def segment_text(text):
    if not text:
        return []
    return list(jieba.cut(text))

def create_vocabulary(data):
    words = set()
    for record in data:
        if len(record) >= 2:
            words.update(segment_text(record[1]))
    return words

def write_vocab_file(vocab, file_path):
    try:
        with open(file_path, 'w', encoding='utf-8') as file:
            for index, word in enumerate(vocab, start=1):
                file.write(f"{word}\t{index}\n")
    except Exception as e:
        print(f"Error writing vocabulary file: {e}")

if __name__ == "__main__":
    dataset_file = "dataset.txt"
    vocab_file = "vocab.txt"

    dataset = load_dataset(dataset_file)
    if dataset:
        vocab = create_vocabulary(dataset)
        write_vocab_file(vocab, vocab_file)
        print(f"Vocabulary saved to '{vocab_file}'.")
    else:
        print("Unable to load dataset. No vocabulary created.")
```

3. Run the script using `python process_dataset.py`. The script will read the dataset from `dataset.txt`, process it, and create the `vocab.txt` file.

