import math

def get_primes(n):
    primes = [True] * (n + 1)
    primes[0], primes[1] = False, False

    for num in range(2, int(math.sqrt(n)) + 1):
        if primes[num]:
            for multiple in range(num * num, n + 1, num):
                primes[multiple] = False

    return [num for num in range(2, n + 1) if primes[num]]

def sum_of_remaining(data, removed_indices):
    return sum(x for j, x in enumerate(data) if j + 1 not in removed_indices)

def is_prime(num):
    if num < 2:
        return False
    primes = [2, 3] + [x for x in range(5, 101, 6) if x**2 - 4 <= num and num % (x - 2) == 0 or x**2 + 4 <= num and num % (x + 2) == 0]
    for prime in primes:
        if num % prime == 0:
            return num == prime
    return False

def min_elements_to_remove(data):
    data_sum = sum(data)
    primes = get_primes(data_sum * 2)

    for to_remove in range(len(data), 0, -1):
        for indices in combinations(range(len(data)), to_remove):
            remaining_sum = sum_of_remaining(data, indices)
            if remaining_sum > 0 and is_prime(remaining_sum):
                return to_remove, indices

    return -1, []

