2. Create a new Python file (e.g., `pulp_cli.py`) and add the following code to implement the CLI application:

```python
import os
import toml
from click import ClickException, clear, confirm, edit, echo, password_option, echo_via_pager
from getpass import getpass
from pathlib import Path

CONFIG_FILE = "pulp-cli.toml"

def load_config():
    if not Path(CONFIG_FILE).exists():
        return {}
    return toml.load(CONFIG_FILE)

def save_config(config):
    with open(CONFIG_FILE, "wt") as f:
        toml.dump(config, f)

def get_sensitive_value(name, default=None):
    value = default
    if name in config:
        value = config[name]
    elif default is None:
        value = getpass(f"Enter {name}: ")
    else:
        value = default
    return value

def validate_config(config):
    required_fields = ["base_url", "format"]
    for field in required_fields:
        if field not in config:
            raise ClickException(f"Required field '{field}' is missing")

def create_config():
    config = load_config()

    config["base_url"] = get_sensitive_value("base_url", "http://localhost:8000")
    config["username"] = get_sensitive_value("username")
    config["password"] = get_sensitive_value("password")
    config["cert"] = get_sensitive_value("cert")
    config["key"] = get_sensitive_value("key")
    config["verify_ssl"] = get_sensitive_value("verify_ssl", True)
    config["format"] = get_sensitive_value("format", "table")
    config["dry_run"] = get_sensitive_value("dry_run", False)
    config["timeout"] = get_sensitive_value("timeout", 30)
    config["verbose"] = get_sensitive_value("verbose", False)

    save_config(config)
    echo(f"Configuration created in {CONFIG_FILE}")

@click.command()
@click.option("--interactive", is_flag=True, help="Interactively create a new configuration")
def cli(interactive):
    global config
    config = load_config()

    if interactive:
        create_config()
    else:
