        echo("Aborting")
        return

    editor = os.environ.get("EDITOR", "nano")
    clear()
    echo_via_pager(f"Editing {CONFIG_FILE} with {editor}...")
    os.system(f"{editor} {CONFIG_FILE}")

@cli.command()
@password_option(confirm=True)
@click.argument("new_password")
def change_password(new_password):
    """Change the password in the configuration file"""
    config = load_config()
    config["password"] = new_password
    save_config(config)
    echo(f"Password changed in {CONFIG_FILE}")

@cli.command()
def validate():
    """Validate the configuration file"""
    try:
        validate_config(load_config())
        echo(f"{CONFIG_FILE} is valid")
    except ClickException as e:
        raise ClickException(e.format_message())

