```python
import numpy as np
import pandas as pd
import cupy as cp
import cupyx
import timeit

from scipy.ndimage import gaussian_filter, minimum_filter, maximum_filter, median_filter, percentile_filter, rank_filter, convolve, correlate
from scipy.ndimage.filters import uniform_filter
from scipy.stats import norm

class ImageBench:
    def __init__(self, image_shape, filter_sizes, data_type, seed=42):
        self.image_shape = image_shape
        self.filter_sizes = filter_sizes
        self.data_type = data_type
        self.seed = seed

    def setup_image(self):
        rng = np.random.RandomState(self.seed)
        image = rng.normal(size=self.image_shape).astype(self.data_type)
        return image

    def setup_filter(self, filter_size):
        raise NotImplementedError

class FilterBench(ImageBench):
    def __init__(self, image_shape, filter_sizes, data_type, seed=42):
        super().__init__(image_shape, filter_sizes, data_type, seed)

    def setup_filter(self, filter_size):
        if isinstance(filter_size, int):
            filter_size = (filter_size,) * len(self.image_shape)
        if not all(isinstance(dim, int) for dim in filter_size):
            raise ValueError("Filter size must be an integer or tuple of integers.")
        if not all(dim > 0 for dim in filter_size):
            raise ValueError("Filter size must have positive dimensions.")
        if not all(dim <= dim_img for dim, dim_img in zip(filter_size, self.image_shape)):
            raise ValueError("Filter size must be smaller than or equal to image dimensions.")

        filter_func = {
            'uniform': uniform_filter,
            'gaussian': lambda: gaussian_filter(self.image, sigma=np.array(filter_size) / 3),
            'minimum': minimum_filter,
            'maximum': maximum_filter,
            'median': median_filter,
            'percentile': lambda: percentile_filter(self.image, q=50, footprint=tuple(filter_size)),
            'rank': lambda: rank_filter(self.image, rank=0.5, footprint=tuple(filter_size))
        }

        return filter_func, filter_size

class ConvolveBench(ImageBench):
    def __init__(self, image_shape, filter_sizes, data_type, seed=42):
        super().__init__(image_shape, filter_sizes, data_type, seed)

    def setup_filter(self, filter_size):
        if isinstance(filter_size, int):
            filter_size = (filter_size,) * len(self.image_shape)
        if not all(isinstance(dim, int) for dim in filter_size):
            raise ValueError("Filter size must be an integer or tuple of integers.")
        if not all(dim > 0 for dim in filter_size):
            raise ValueError("Filter size must have positive dimensions.")

        filter_func = {
            'correlation_1D': lambda: correlate(self.image, np.ones(filter_size), mode='wrap'),
            'convolution_1D': lambda: convolve(self.image, np.ones(filter_size), mode='valid'),
            'correlation_2D': lambda: correlate(self.image, np.ones((filter_size, filter_size)), mode='wrap'),
            'convolution_2D': lambda: convolve(self.image, np.ones((filter_size, filter_size)), mode='valid')
        }

        return filter_func, filter_size

def benchmark_filter(filter_bench, repetitions=10):
    df_results = pd.DataFrame(columns=['filter_type', 'filter_size', 'operation_time'])

    for filter_type, filter_size in zip(filter_bench.filter_func.keys(), filter_bench.filter_sizes):
        filter_func, _ = filter_bench.setup_filter(filter_size)

        t = timeit.timeit(lambda: filter_func(filter_bench.image), number=repetitions)
        df_results = df_results.append({
            'filter_type': filter_type,
            'filter_size': filter_size,
            'operation_time': t
        }, ignore_index=True)

    return df_results

def benchmark_convolve(convolve_bench, repetitions=10):
    df_results = pd.DataFrame(columns=['filter_type', 'filter_size', 'operation_time'])

    for filter_type, filter_size in zip(convolve_bench.filter_func.keys(), convolve_bench.filter_sizes):
        filter_func, _ = convolve_bench.setup_filter(filter_size)

        t = timeit.timeit(lambda: filter_func(convolve_bench.image), number=repetitions)
        df_results = df_results.append({
            'filter_type': filter_type,
            'filter_size': filter_size,
            'operation_time': t
        }, ignore_index=True)

    return df_results

if __name__ == '__main__':
    image_shapes = [(100,), (200, 200), (300, 300, 300)]
    filter_sizes = [3, 5, 7]
    data_types = [np.float32, np.float64]

    for data_type in data_types:
        for image_shape in image_shapes:
            filter_bench = FilterBench(image_shape, filter_sizes, data_type)
            df_filter_results = benchmark_filter(filter_bench)

            convolve_bench = ConvolveBench(image_shape, filter_sizes, data_type)
            df_convolve_results = benchmark_convolve(convolve_bench)

            result_df = pd.concat([df_filter_results, df_convolve_results], axis=0)
            result_df.to_csv(f'results_{data_type}_{image_shape}.csv', index=False)
            result_df.to_pickle(f'results_{data_type}_{image_shape}.pkl')
