class TestLambdaHandler(unittest.TestCase):
    def setUp(self):
        self.s3 = boto3.client("s3", region_name="us-east-1")
        self.lambda_function = lambda_handler

    def test_valid_input(self):
        # Create a test S3 object
        test_bucket = "test-bucket-for-lambda"
        self.s3.create_bucket(Bucket=test_bucket)
        test_key = "test-object.txt"
        self.s3.put_object(Bucket=test_bucket, Key=test_key, Body="Test content")

        # Trigger the Lambda function with a valid S3 event
        test_event = {
            "Records": [
                {
                    "s3": {
                        "bucket": {"name": test_bucket},
                        "object": {"key": test_key},
                    }
                }
            ]
        }

        response = self.lambda_function(test_event, None)

        # Verify the response
        self.assertDictEqual(
            response, {"content": "Test content", "event_details": test_event}
        )

    def test_invalid_bucket(self):
        # Trigger the Lambda function with an invalid S3 event
        test_event = {
            "Records": [
                {
                    "s3": {
                        "bucket": {"name": "nonexistent-bucket"},
                        "object": {"key": "nonexistent-object.txt"},
                    }
                }
            ]
        }

        with self.assertRaises(Exception) as cm:
            self.lambda_function(test_event, None)

        # Verify the error message
        self.assertIn("Error getting S3 object", str(cm.exception))

    def tearDown(self):
        # Clean up the test S3 object
        test_bucket = "test-bucket-for-lambda"
        test_key = "test-object.txt"
        try:
            self.s3.delete_object(Bucket=test_bucket, Key=test_key)
        except Exception as e:
            logger.exception(f"Error deleting S3 object {test_bucket}/{test_key}: {e}")

        try:
            self.s3.delete_bucket(Bucket=test_bucket)
        except Exception as e:
            logger.exception(f"Error deleting S3 bucket {test_bucket}: {e}")


if __name__ == "__main__":
    unittest.main()
