def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_primes_in_range(start, end):
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def get_valid_integer_input(prompt):
    while True:
        try:
            num = int(input(prompt))
            if num > 1:
                return num
            else:
                print("Please enter an integer greater than 1.")
        except ValueError:
            print("Invalid input. Please enter an integer greater than 1.")

if __name__ == "__main__":
    start = get_valid_integer_input("Enter the start of the range: ")
    end = get_valid_integer_input("Enter the end of the range: ")

    primes = find_primes_in_range(start, end)

    if primes:
        print("Prime numbers in the given range are:")
        for prime in primes:
            print(prime)
    else:
        print("There are no prime numbers in the given range.")
```

