from django.contrib.auth.models import AbstractBaseUser, BaseUserManager, PermissionsMixin
from django.db import models

class CustomUserManager(BaseUserManager):
    def create_user(self, dni, username, password=None, **extra_fields):
        if not dni:
            raise ValueError("The DNI field must be set")
        if not username:
            raise ValueError("The Username field must be set")

        user = self.model(dni=dni, username=username, **extra_fields)
        user.set_password(password)
        user.save(using=self._db)
        return user

    def create_superuser(self, dni, username, password=None, **extra_fields):
        user = self.create_user(dni, username, password, **extra_fields)
        user.is_superuser = True
        user.is_staff = True
        user.save(using=self._db)
        return user

class Role(models.Model):
    name = models.CharField(max_length=50)

    def __str__(self):
        return self.name

class Permission(models.Model):
    name = models.CharField(max_length=50)

    def __str__(self):
        return self.name

class UserRole(models.Model):
    user = models.OneToOneField('User', on_delete=models.CASCADE)
    role = models.ForeignKey(Role, on_delete=models.CASCADE)

    def __str__(self):
        return f"{self.user.username}'s role"

class RolePermission(models.Model):
    role = models.ForeignKey(Role, on_delete=models.CASCADE)
    permission = models.ForeignKey(Permission, on_delete=models.CASCADE)

    def __str__(self):
        return f"{self.role.name} has {self.permission.name}"

class User(AbstractBaseUser, PermissionsMixin):
    dni = models.CharField(max_length=50, unique=True)
    username = models.CharField(max_length=50, unique=True)
    password = models.CharField(max_length=128)
    is_active = models.BooleanField(default=True)
    is_staff = models.BooleanField(default=False)
    date_joined = models.DateTimeField(auto_now_add=True)

    objects = CustomUserManager()

    USERNAME_FIELD = 'dni'
    REQUIRED_FIELDS = ['username']

    def get_role(self):
        return self.userrole.role

    def __str__(self):
        return self.username

