import requests
from bs4 import BeautifulSoup
import json

def get_one_page(url, headers):
    try:
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.text
        else:
            print(f"Failed to get content from {url}. Status code: {response.status_code}")
            return None
    except Exception as e:
        print(f"Error occurred when sending GET request: {e}")
        return None

def parse_one_page(html):
    soup = BeautifulSoup(html, 'html.parser')
    movie_list = soup.find_all('dd')
    for movie in movie_list:
        rank = int(movie.find('i', class_='board-index').text.strip())
        cover_image_url = movie.find('img')['data-src']
        title = movie.find('p', class_='name').find('a').text.strip()
        main_actors = movie.find('p', class_='star').text.strip()[11:] # Remove the "Main Actors: " part
        release_time = movie.find('p', class_='releasetime').text.strip()[13:] # Remove the "Release Time: " part
        rating = float('{}.{}'.format(
            movie.find('i', class_='integer').text.strip(),
            movie.find('i', class_='fraction').text.strip()
        ))

        yield {
            'rank': rank,
            'cover_image_url': cover_image_url,
            'title': title,
            'main_actors': main_actors,
            'release_time': release_time,
            'rating': rating
        }

def write_to_file(content):
    with open('movies.json', 'w') as f:
        json.dump(content, f, indent=2)

def main(offset):
    url = f'http://fictional-movie-site.com/board/4?offset={offset}'
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.36 Edge/16.16299'
    }
    html = get_one_page(url, headers)
    if html:
        movies = parse_one_page(html)
        movie_list = list(movies)
        write_to_file(movie_list)

if __name__ == '__main__':
    for offset in range(0, 100, 10):
        main(offset)

