import uuid

class FinancialTransaction:
    def __init__(self, message_type):
        if message_type not in ['Transaction', 'Confirmation']:
            raise ValueError("Invalid message type. Must be 'Transaction' or 'Confirmation'.")
        self.message_type = message_type
        self._data = {}

    @property
    def data(self):
        return self._data

    @data.setter
    def data(self, details):
        if self.message_type == 'Transaction':
            if not all(key in details for key in ('sender', 'receiver', 'amount', 'currency', 'transaction_id')):
                raise ValueError("Invalid transaction data. Must include 'sender', 'receiver', 'amount', 'currency', and 'transaction_id'.")
            if not all(isinstance(value, str) for value in (details['sender'], details['receiver'], details['transaction_id'])):
                raise ValueError("Invalid data type. 'sender', 'receiver', and 'transaction_id' must be strings.")
            if not isinstance(details['amount'], (int, float)) or details['amount'] < 0:
                raise ValueError("Invalid amount. Must be a non-negative number.")
            if not isinstance(details['currency'], str):
                raise ValueError("Invalid currency. Must be a string.")
            self._data = details

        elif self.message_type == 'Confirmation':
            if not all(key in details for key in ('transaction_id', 'success')):
                raise ValueError("Invalid confirmation data. Must include 'transaction_id' and 'success'.")
            if not isinstance(details['transaction_id'], str):
                raise ValueError("Invalid data type. 'transaction_id' must be a string.")
            if not isinstance(details['success'], bool):
                raise ValueError("Invalid data type. 'success' must be a boolean.")
            self._data = details

    def is_consistent(self):
        if self.message_type == 'Transaction':
            if not self.data.get('transaction_id').isalnum():
                return False
            if self.data.get('amount') < 0:
                return False
            return True

        elif self.message_type == 'Confirmation':
            if not self.data.get('transaction_id').isalnum():
                return False
            if not isinstance(self.data.get('success'), bool):
                return False
            return True

# Example usage
transaction = FinancialTransaction('Transaction')
transaction.data = {
    'sender': 'Alice',
    'receiver': 'Bob',
    'amount': 100,
    'currency': 'USD',
    'transaction_id': str(uuid.uuid4())
}
print(transaction.is_consistent())

confirmation = FinancialTransaction('Confirmation')
confirmation.data = {
    'transaction_id': transaction.data['transaction_id'],
    'success': True
}
print(confirmation.is_consistent())
```

