from threading import Thread

# Set up logging
logging.basicConfig(filename='ble_scanner.log', level=logging.DEBUG,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Define a set of beacons to track by their unique identifiers
BEACONS_TO_TRACK = {
    "beacon1": "11:22:33:44:55:66",
    "beacon2": "77:88:99:AA:BB:CC"
}

def scan_ble_beacons(sock):
    """Continuously scans for BLE beacons and parses the events to get the RSSI values."""
    global BEACONS_TO_TRACK

    try:
        hci_le_set_scan_parameters(sock)
        hci_enable_le_scan(sock)

        while True:
            beacons_data = parse_events(sock, 1)
            send_beacon_data(beacons_data)

    except KeyboardInterrupt:
        logging.info("Scanning stopped by user.")
    except Exception as e:
        logging.error(f"Error while scanning BLE beacons: {e}")
    finally:
        sock.close()


def send_beacon_data(beacons_data):
    """Sends the RSSI values of the detected beacons through the UART interface."""
    for beacon_id, rssi in beacons_data.items():
        if beacon_id in BEACONS_TO_TRACK:
            uart_data = f"{beacon_id}:{rssi}"
            try:
                sendData(uart_data)
                logging.debug(f"Sent data: {uart_data}")
            except Exception as e:
                logging.error(f"Error while sending UART data: {e}")


def main():
    logging.info("Starting BLE scanner...")

    # Initialize the Bluetooth socket
    try:
        sock = socket.socket(socket.AF_BLUETOOTH, socket.SOCK_RAW, socket.BTPROTO_LE)
    except Exception as e:
        logging.error(f"Error initializing Bluetooth socket: {e}")
        return

    # Start the scanning thread
    scan_thread = Thread(target=scan_ble_beacons, args=(sock,))
    scan_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Closing BLE scanner...")
        sendData("Scanner closing...\n")

    # Close the UART port and join the scanning thread
    uart.closeport()
    scan_thread.join()


if __name__ == "__main__":
    main()
