def validate_job_exists(job_name):
    def decorator(func):
        if job_name and job_name not in job_registry:
            raise ValueError(f"Job '{job_name}' does not exist.")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        wrapper.depends_on = job_name
        return wrapper
    return decorator

def job(desc=None, **deps):
    def decorator(func):
        for job_name, depends_on in deps.items():
            if depends_on and depends_on not in job_registry:
                raise ValueError(f"Dependency job '{depends_on}' for job '{job_name}' does not exist.")
        func.__dict__["_description"] = desc
        func.__dict__["_dependencies"] = deps
        return validate_job_exists(job_name)(func)
    return decorator

job_registry = {}

def register_job(func):
    job_name = func.__name__
    job_registry[job_name] = func
    return func

@register_job
@job(desc="Computes the square of a number.", deps={"cube": "cube"})
def square(x, *, cube):
    return x ** 2, {"result": f"Square of {x} is {result}."}

@register_job
@job(desc="Computes the cube of a number.", deps={"square": "square"})
def cube(x, *, square):
    result = x ** 3
    deps_result = square(square["result"])
    return result, {**deps_result[1], **{"cube": f"Cube of {x} is {result}."}}

def run_job(job_name):
    if job_name not in job_registry:
        raise ValueError(f"Job '{job_name}' does not exist.")
    job_func = job_registry[job_name]
    depends_on = job_func.depends_on

    if depends_on:
        run_job(depends_on)

    result, description = job_func(**job_func.__dict__["_dependencies"])
    print(description[description.keys() & description.get("result").keys()])

def list_jobs():
    for job_name, job_func in job_registry.items():
        deps = job_func.__dict__.get("_dependencies", {})
        depends_on_str = ", ".join([f"{k}" for k in deps.keys()])
        print(f"Job: {job_name}, Description: {job_func.__dict__.get('_description')}, Depends on: {depends_on_str}")

if __name__ == "__main__":
    list_jobs()
    run_job("cube")  # Replace this with any job name you want to run
