        self.loads = list(map(int, input(f"Enter {self.n} loads: ").split()))
        if len(self.loads) != self.n:
            raise ValueError("Invalid number of loads provided")

    def calculate_balance_moves(self) -> int:
        total_load = sum(self.loads)
        avg_load = total_load // self.n

        if total_load % self.n != 0:
            return -1

        moves = 0
        for i, load in enumerate(self.loads):
            if load > avg_load:
                extra_load = load - avg_load
                self.loads[i] -= extra_load
                moves += extra_load

        return moves

def main():
    while True:
        n = int(input("Enter the number of servers (-1 to quit): "))
        if n == -1:
            break

        lb = LoadBalancer(n)
        lb.add_load()
        moves = lb.calculate_balance_moves()

        if moves != -1:
            print(f"Minimum number of moves required: {moves}")
        else:
            print("Balancing not possible")

