```python
from functools import lru_cache

@lru_cache(maxsize=None)
def sum_proper_divisors(n: int) -> int:
    if n < 2:
        return 0
    divs = set(d for d in range(1, int(n ** 0.5) + 1) if n % d == 0)
    return sum(divs) + (sum(d for d in divs if d != n // d) if n // divs[-1] != divs[-1] else 0)

def find_amicable_pairs(n: int) -> List[Tuple[int, int]]:
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer")
    amicable_pairs = []
    for num in range(2, n):
        pair = (num, sum_proper_divisors(num))
        if pair[1] < n and sum_proper_divisors(pair[1]) == num and pair[0] != pair[1]:
            amicable_pairs.append(pair)
    return amicable_pairs
```

