        if not isinstance(session_data, dict):
            raise ValueError("Session data must be a dictionary.")

    def _validate_session_key(self, session_key: str) -> None:
        if not isinstance(session_key, str) or not session_key:
            raise ValueError("Session key must be a non-empty string.")

    def load_session(self, session_key: str) -> Dict[str, Any]:
        self._validate_session_key(session_key)
        try:
            response = self.table.get_item(Key={"session_key": session_key})
            item = response["Item"]
            return {k: v for k, v in item.items() if k != "session_data_encrypted"} | json.loads(item["session_data_encrypted"])
        except ClientError as e:
            if e.response["Error"]["Code"] == "ResourceNotFoundException":
                return {}
            else:
                raise

    def session_exists(self, session_key: str) -> bool:
        self._validate_session_key(session_key)
        try:
            response = self.table.get_item(Key={"session_key": session_key})
            return "Item" in response
        except ClientError as e:
            if e.response["Error"]["Code"] == "ResourceNotFoundException":
                return False
            else:
                raise

    def create_session(self, session_key: str, session_data: Dict[str, Any]) -> None:
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        if self.session_exists(session_key):
            raise ValueError(f"Session with key {session_key} already exists.")
        self.table.put_item(
            Item={
                "session_key": session_key,
                "session_data_encrypted": json.dumps(session_data),
            }
        )

    def save_session(self, session_key: str, session_data: Dict[str, Any]) -> None:
        self._validate_session_key(session_key)
        self._validate_session_data(session_data)
        if not self.session_exists(session_key):
            raise ValueError(f"Session with key {session_key} does not exist.")
        self.table.update_item(
            Key={"session_key": session_key},
            UpdateExpression="set session_data_encrypted = :encrypted_data",
            ExpressionAttributeValues={":encrypted_data": json.dumps(session_data)},
        )

    def delete_session(self, session_key: str) -> None:
        self._validate_session_key(session_key)
        if not self.session_exists(session_key):
            raise ValueError(f"Session with key {session_key} does not exist.")
        self.table.delete_item(Key={"session_key": session_key})
