        self.assertTrue(self.session_store.session_exists("test_session"))

    def test_create_session_existing(self):
        self.dynamodb_table.get_item.return_value = {"Item": {"session_key": "test_session"}}
        with self.assertRaises(ValueError):
            self.session_store.create_session("test_session", {"key": "value"})

    def test_create_session_new(self):
        self.session_store.create_session("test_session", {"key": "value"})
        self.dynamodb_table.put_item.assert_called_once()

    def test_save_session_nonexistent(self):
        self.dynamodb_table.get_item.return_value = {"Item": None}
        with self.assertRaises(ValueError):
            self.session_store.save_session("test_session", {"key": "value"})

    def test_save_session_valid(self):
        self.dynamodb_table.get_item.return_value = {"Item": {"session_key": "test_session"}}
        self.session_store.save_session("test_session", {"key": "value"})
        self.dynamodb_table.update_item.assert_called_once()

    def test_delete_session_nonexistent(self):
