```python
from pymongo import MongoClient, ReturnDocument
from datetime import datetime
from bson.objectid import ObjectId

# Connect to the MongoDB server
client = MongoClient("mongodb://localhost:27017/")

# Access the desired database
db = client["employee_attendance"]

# Get collections
attendance_col = db["attendance"]
emp_col = db["emp"]


def is_valid_date(date_text):
    try:
        return datetime.strptime(date_text, "%Y-%m-%d")
    except ValueError:
        return False


def is_valid_employee_id(employee_id):
    return ObjectId.is_valid(employee_id)


def insert_attendance_record(employee_id, employee_name, date):
    if not is_valid_employee_id(employee_id) or not is_valid_date(date):
        return False

    attendance_record = {"employee_id": employee_id, "name": employee_name, "date": date}
    result = attendance_col.insert_one(attendance_record)
    return result.inserted_id is not None


def fetch_all_attendance_records():
    attendance_list = []
    for record in attendance_col.find():
        attendance_list.append({
            "employee_id": str(record["employee_id"]),
            "name": record["name"],
            "date": str(record["date"]),
            "time": record["time"]
        })
    return attendance_list


def fetch_attendance_records_by_date(date):
    if not is_valid_date(date):
        return []

    attendance_list = []
    for record in attendance_col.find({"date": date}):
        attendance_list.append({
            "employee_id": str(record["employee_id"]),
            "name": record["name"],
            "date": str(record["date"]),
            "time": record["time"]
