    if not is_valid_employee_id(employee_id):
        return []

    attendance_list = []
    for record in attendance_col.find({"employee_id": employee_id}):
        attendance_list.append({
            "employee_id": str(record["employee_id"]),
            "name": record["name"],
            "date": str(record["date"]),
            "time": record["time"]
        })
    return attendance_list


def fetch_attendance_records_by_employee_id_and_date(employee_id, date):
    if not is_valid_employee_id(employee_id) or not is_valid_date(date):
        return []

    attendance_list = []
    query = {"employee_id": employee_id, "date": date}
    for record in attendance_col.find(query):
        attendance_list.append({
            "employee_id": str(record["employee_id"]),
            "name": record["name"],
            "date": str(record["date"]),
            "time": record["time"]
        })
    return attendance_list


def get_employee_contact_phone_number(employee_id):
    if not is_valid_employee_id(employee_id):
        return None

    employee = emp_col.find_one({"_id": ObjectId(employee_id)})
    if employee and "contact_info" in employee and "phone_number" in employee["contact_info"]:
        return employee["contact_info"]["phone_number"]
    return None


