```python
import re

class BotModule:
    def __init__(self, bot):
        self.bot = bot

    def handle_message(self, message):
        cmd_match = re.match(r'\.(echo|other_cmd) (.*)', message)
        if cmd_match:
            cmd_name, cmd_args = cmd_match.groups()
            getattr(self, f'handle_cmd_{cmd_name}', self.handle_default)(cmd_args)
        else:
            self.handle_default(message)

    def handle_cmd_echo(self, args):
        if args:
            msg = f'Echo: {args}'
        else:
            msg = f'Echo: {self.bot.nickname}'
        self.bot.connection.msg_privmsg(msg)

    def handle_default(self, message):
        print(f'Unhandled message: {message}')


class EchoModule(BotModule):
    def __init__(self, bot):
        super().__init__(bot)

    def handle_cmd_echo(self, args):
        super().handle_cmd_echo(args)


class Connection:
    def __init__(self):
        pass

    def msg_privmsg(self, message):
        print(f'< {message}')


class Bot:
    def __init__(self, nickname, connection):
        self.nickname = nickname
        self.connection = connection
        self.modules = [EchoModule(self)]

    def handle_message(self, message):
        for module in self.modules:
            module.handle_message(message)


def test_echo_module():
    conn = Connection()
    bot = Bot('test_bot', conn)

    # Test echo with no arguments
    bot.handle_message('.echo')

    # Test echo with arguments
    bot.handle_message('.echo test_message')

    # Test unhandled command
    bot.handle_message('.unknown_cmd')

test_echo_module()
```

