```python
from pyinputplus import inputInt, validators

class Calculator:
    def add(self, num1, num2):
        return num1 + num2

    def subtract(self, num1, num2):
        return num1 - num2

    def multiply(self, num1, num2):
        return num1 * num2

    def divide(self, num1, num2):
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        return num1 / num2


def main():
    calculator = Calculator()

    num1 = inputInt("Enter the first number: ", validators=validators.numbers)
    num2 = inputInt("Enter the second number: ", validators=validators.numbers)

    operation = input("Select an operation (+, -, *, /): ").lower()

    if operation == "+":
        result = calculator.add(num1, num2)
    elif operation == "-":
        result = calculator.subtract(num1, num2)
    elif operation == "*":
        result = calculator.multiply(num1, num2)
    elif operation == "/":
        try:
            result = calculator.divide(num1, num2)
        except ValueError as e:
            print(e)
            return
    else:
        print("Invalid operation. Please use +, -, *, or /.")
        return

    print(f"The result is: {result}")


if __name__ == "__main__":
    main()
```

