def delete_elements_at_indices(my_list, indices):
    # Create a new list with the same elements as my_list
    new_list = my_list.copy()

    # Iterate over the indices list
    for index in sorted(indices, reverse=True):
        # Check if the index is within the range of the new_list
        if 0 <= index < len(new_list):
            # Remove the element at the given index from new_list
            del new_list[index]

    return new_list

