            client.collection.append(title)
            self._catalogue[title] -= 1
        else:
            print(f"Sorry, the book '{title}' is not available")

    def inventory(self):
        for title, quantity in self._catalogue.items():
            print(f"There are {quantity} copies of '{title}' left.")

