import random
from collections import defaultdict
import unittest

def is_valid_input(pa, q, n):
    return 0 <= pa <= 1 and 0 <= q <= 1 and n > 0

def calculate_success_rate(outcomes, total):
    if total == 0:
        return 0
    return outcomes / total

def calculate_chi_squared(observed, expected):
    return sum((o - e) ** 2 / e for o, e in zip(observed, expected))

def run_ab_test_simulation(pa, q, n):
    if not is_valid_input(pa, q, n):
        raise ValueError("Invalid input parameters")

    random.seed(42)
    version_outcomes = defaultdict(int)

    for _ in range(n):
        show_version_a = random.random() < pa
        if show_version_a:
            success = random.random() < q
            version_outcomes['A'] += int(success)
            version_outcomes['not_A'] += int(not success)
        else:
            success = random.random() > q
            version_outcomes['B'] += int(success)
            version_outcomes['not_B'] += int(not success)

    success_rates = {
        'A': calculate_success_rate(version_outcomes['A'], version_outcomes['A'] + version_outcomes['not_A']),
        'B': calculate_success_rate(version_outcomes['B'], version_outcomes['B'] + version_outcomes['not_B'])
    }

    observed = [version_outcomes['A'], version_outcomes['not_A'], version_outcomes['B'], version_outcomes['not_B']]
    expected = [pa * n * q, pa * n * (1 - q), (1 - pa) * n * (1 - q), (1 - pa) * n * q]

    chi_squared = calculate_chi_squared(observed, expected)
    p_value = 1 - stats.chi2.cdf(chi_squared, 1)

    return success_rates, chi_squared, p_value

class TestRunAbTestSimulation(unittest.TestCase):
    def test_valid_input(self):
        with self.assertRaises(ValueError):
            run_ab_test_simulation(-0.1, 0.5, 100)

        with self.assertRaises(ValueError):
            run_ab_test_simulation(0.5, 1.1, 100)

        with self.assertRaises(ValueError):
            run_ab_test_simulation(0.5, 0.5, -10)

    def test_correct_success_rates(self):
        success_rates, _, _ = run_ab_test_simulation(0.7, 0.3, 1000)
        self.assertAlmostEqual(success_rates['A'], 0.3, places=2)
        self.assertAlmostEqual(success_rates['B'], 0.2, places=2)

    def test_correct_chi_squared(self):
        _, chi_squared, _ = run_ab_test_simulation(0.7, 0.3, 1000)
        self.assertAlmostEqual(chi_squared, 10.58, places=2)

    def test_correct_p_value(self):
        _, _, p_value = run_ab_test_simulation(0.7, 0.3, 1000)
        self.assertAlmostEqual(p_value, 0.0011, places=3)

if __name__ == "__main__":
    unittest.main()
```

