import os
from collections import defaultdict

def normalize(text):
    """Normalize text data."""
    result = []
    for char in text:
        cat = unicodedata.category(char)
        if cat == "Lu" or cat == "Ll" or cat.startswith("N") or cat == "Sk":
            result.append(char.lower())
        elif char == " " and result[-1] != "-":
            result.append(" ")
    return "".join(result)

def count_skills(profiles):
    """Extract and count the frequency of each skill across all profiles."""
    all_skills = defaultdict(int)
    for profile in profiles:
        for skill, years in profile["skills"].items():
            all_skills[skill] += years
    return dict(all_skills)

def count_skills_by_category(profiles):
    """Extract and count the frequency of each skill within each job category."""
    skill_categories = defaultdict(lambda: defaultdict(int))
    for profile in profiles:
        for skill, years in profile["skills"].items():
            category = profile["category"]
            skill_categories[category][skill] += years
    return dict(skill_categories)

def process_json_files(directory):
    """Process JSON files in a directory."""
    for filename in os.listdir(directory):
        if filename.endswith(".json"):
            filepath = os.path.join(directory, filename)
            with open(filepath, "r", encoding="utf-8") as f:
                try:
                    profile = json.load(f)
                except json.JSONDecodeError as e:
                    print(f"Error processing {filename}: {e}")
                    continue

                # Normalize text data
                profile["name"] = normalize(profile["name"])
                profile["bio"] = normalize(profile["bio"])

                # Assign a unique candidate ID
                if "id" not in profile:
                    profile["id"] = f"candidate_{len(profiles)}"

                # Extract and count the frequency of each skill
                profile["skill_counts"] = count_skills([profile])

                # Extract and count the frequency of each skill within each job category
                profile["category_skill_counts"] = count_skills_by_category([profile])

                # Identify and extract the years of experience associated with each skill
                profile["skill_experience"] = {
                    skill: years for skill, years in profile["skills"].items()
                }

                # Write the updated candidate profile back to the JSON file
                with open(filepath, "w", encoding="utf-8") as f:
                    json.dump(profile, f, ensure_ascii=False, indent=2)

def main():
    # Process JSON files
    process_json_files("path/to/json/files")

    # Invoke the merge_ids_duplicates module
    import merge_ids_duplicates

if __name__ == "__main__":
