```python
import unittest
import sys

def python_plugin():
    def hello():
        return "Hello from Python!"
    return hello

def js_plugin():
    def hello():
        return "Olá from JavaScript!"
    return hello

def xhtml_plugin():
    def hello():
        return "Bonjour from XHTML!"
    return hello

class PluginManager:
    def __init__(self):
        self.plugins = {}

    def load_plugins(self):
        try:
            self.plugins["python"] = python_plugin()
        except ImportError:
            print("Error importing Python plugin")

        try:
            self.plugins["js"] = js_plugin()
        except ImportError:
            print("Error importing JS plugin")

        try:
            self.plugins["xhtml"] = xhtml_plugin()
        except ImportError:
            print("Error importing XHTML plugin")

    def list_plugins(self):
        return [name for name in self.plugins if callable(self.plugins[name])]

    def is_plugin_available(self, plugin_name):
        return plugin_name in self.plugins and callable(self.plugins[plugin_name])

def main():
    plugin_manager = PluginManager()
    plugin_manager.load_plugins()
    print("Available plugins:", plugin_manager.list_plugins())

class TestPluginManager(unittest.TestCase):
    def setUp(self):
        self.plugin_manager = PluginManager()

    def test_list_plugins_empty(self):
        self.assertEqual(self.plugin_manager.list_plugins(), [])

    def test_is_plugin_available_false(self):
        self.plugin_manager.load_plugins()
        self.assertFalse(self.plugin_manager.is_plugin_available("nonexistent"))

if __name__ == "__main__":
    main()
    unittest.main(argv=sys.argv[:1])
