```python
import pandas as pd
import numpy as np

class LinearPearsonAnomalyDetector:
    def __init__(self):
        self.data = pd.DataFrame()
        self.correlation_threshold = 0

    def train(self, values):
        if not values:
            raise ValueError("Input list cannot be empty.")

        if not all(isinstance(val, (int, float)) for val in values):
            raise TypeError("All values in the input list must be numerical types.")

        self.data = pd.DataFrame({'value': values, 'index': range(len(values))})
        self.correlation_threshold = self.data.drop(columns='value').corrwith(self.data['value']).abs().iloc[0]

    def is_anomalous(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("New value must be a numerical type.")

        self.data = self.data.append({'value': value, 'index': len(self.data)}, ignore_index=True)
        new_correlation = self.data.drop(columns='value').corrwith(self.data['value']).abs().iloc[0]

        return new_correlation < self.correlation_threshold
```

