```python
import csv
from datetime import datetime

def read_csv(file_name, mode):
    try:
        with open(file_name, mode, newline='') as file:
            reader = csv.reader(file, delimiter=',')
            header = next(reader) if mode == 'r' else []
            return reader, header
    except FileNotFoundError:
        print(f"Error: The file '{file_name}' does not exist.")
        return [], []

def process_texts(texts_reader, texts_header):
    if texts_header:
        return [(row[0], row[1], datetime.strptime(row[2], '%d-%m-%Y %H:%M')) for row in texts_reader]
    else:
        return []

def process_calls(calls_reader, calls_header):
    if calls_header:
        return [(row[0], row[1], datetime.strptime(row[2], '%d-%m-%Y %H:%M'), int(row[3])) for row in calls_reader]
    else:
        return []

def print_result(texts, calls):
    if texts:
        first_text_message = texts[0]
        print(f"First record of text messages: {first_text_message[0]} -> {first_text_message[1]}, {first_text_message[2]}")
    else:
        print("Error: There are no text messages in the provided data.")

    if calls:
        last_call = sorted(calls, key=lambda x: x[2], reverse=True)[0]
        print(f"Last record of phone calls: {last_call[0]} -> {last_call[1]}, {last_call[2]}, {last_call[3]} seconds")
    else:
        print("Error: There are no phone calls in the provided data.")

def main():
    texts_reader, texts_header = read_csv('texts.csv', 'r')
    calls_reader, calls_header = read_csv('calls.csv', 'r')

    texts = process_texts(texts_reader, texts_header)
    calls = process_calls(calls_reader, calls_header)

    print_result(texts, calls)

if __name__ == "__main__":
    main()
```

