from lxml import etree


def get_project_info():
    # This function simulates an API call to Crowdin to get project information in XML format.
    # For the purpose of this exercise, we'll use a pre-defined XML structure as an lxml.etree object.
    xml_data = '''
    <project>
        <files>
            <file path="file1.txt"/>
            <file path="folder1/file2.txt"/>
            <file path="folder1/folder2/file3.txt"/>
            <file path="folder3/file4.txt"/>
        </files>
    </project>
    '''
    return etree.fromstring(xml_data)


def process_item(item, parent_path="/"):
    if item.tag == "file":
        return [f"{parent_path}/{item.get('path')}"]
    elif item.tag == "files":
        return [path for child in item for path in process_item(child, parent_path)]
    else:
        raise ValueError(f"Invalid XML structure: Unknown tag '{item.tag}'")


def main():
    try:
        project_info = get_project_info()
        file_paths = process_item(project_info.find("files"))
        for path in file_paths:
            print(path)
    except Exception as e:
        print(f"Error processing XML data: {e}")


if __name__ == "__main__":
    main()

