    def create_database(self, db_name):
        db_exists_query = f"SELECT SCHEMA_NAME FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = '{db_name}'"
        self.cursor.execute(db_exists_query)
        result = self.cursor.fetchone()

        if not result:
            create_db_query = f"CREATE DATABASE {db_name}"
            self.cursor.execute(create_db_query)
            print(f"Database '{db_name}' created successfully.")
        else:
            print(f"Database '{db_name}' already exists.")

    def create_table(self, table_name, table_schema):
        create_table_query = f"CREATE TABLE IF NOT EXISTS {table_name} ({table_schema})"
        self.cursor.execute(create_table_query)
        self.connection.commit()
        print(f"Table '{table_name}' created successfully.")

    def insert(self, insert_query):
        try:
            self.cursor.execute(insert_query)
            self.connection.commit()
            print("Record inserted successfully.")
        except Error as e:
