import os
import time

class DirectoryTraversal:
    def __init__(self, root_dir):
        if not os.path.isdir(root_dir):
            raise NotADirectoryError(f"The provided path '{root_dir}' is not a valid directory.")
        self.root_dir = os.path.abspath(root_dir)

    def traverse_directory(self):
        start_time = time.time()
        self._process_directory(self.root_dir)
        total_time = time.time() - start_time
        print(f"Total time taken for traversal: {total_time:.4f} seconds")

    def _process_directory(self, path):
        try:
            for item in os.listdir(path):
                full_path = os.path.join(path, item)
                if os.path.isfile(full_path):
                    print(os.path.abspath(full_path))
                elif os.path.isdir(full_path) and os.access(full_path, os.R_OK):
                    self._process_directory(full_path)
                elif not os.access(full_path, os.R_OK):
                    print(f"Permission denied: {os.path.abspath(full_path)}")
        except Exception as e:
            print(f"Error occurred: {e}. Moving on to the next item.")

