class ModelRegistrationError(Exception):
    def __init__(self, model_class):
        self.model_class = model_class
        super().__init__(f"Invalid model type: {model_class}")


class AdminSite:
    def __init__(self):
        self.registry = {}

    def register(self, model_class):
        if not isinstance(model_class, type) or not issubclass(model_class, object):
            raise ModelRegistrationError(model_class)

        model_name = model_class.__name__
        if model_name in self.registry:
            print(f"Model '{model_name}' is already registered.")
            return

        self.registry[model_name] = model_class
        print(f"Model '{model_name}' has been registered.")

    def get_registered_models(self):
        return list(self.registry.keys())


class News:
