```python
import re
import os

common5 = "common5.txt"
word_list = "word-list-5.txt"

def get_common5():
    with open(common5, "r") as f:
        return [line.strip() for line in f.readlines()]

def make_position_pattern(green_letters):
    return "^" + ".*".join(green_letters) + "$"

def make_not_position_pattern(yellow_letters):
    pattern = ""
    for letter in yellow_letters:
        pattern += f"[^{letter}].*"
    return pattern

def make_exclude_pattern(bad_letters):
    return "[^" + "".join(bad_letters) + "]*"

def evaluate_matching_rules(word, green_letters, yellow_letters, bad_letters):
    position_pattern = make_position_pattern(green_letters)
    not_position_pattern = make_not_position_pattern(yellow_letters)
    exclude_pattern = make_exclude_pattern(bad_letters)
    pattern = position_pattern + not_position_pattern + exclude_pattern
    rule = re.compile(pattern, re.IGNORECASE)
    return rule.fullmatch(word)

def print_words(common_words, uncommon_words):
    print("\nPossible words:")
    if common_words:
        print("\nCommon words:")
        for word in common_words:
            print(word)
    if uncommon_words:
        print("\nUncommon words:")
        for word in uncommon_words:
            print(word)

def run_process(common_words, uncommon_words, green_letters, yellow_letters, bad_letters):
    filtered_words = []
    for word in common_words:
        if evaluate_matching_rules(word, green_letters, yellow_letters, bad_letters):
            filtered_words.append(word)
    for word in uncommon_words:
        if evaluate_matching_rules(word, green_letters, yellow_letters, bad_letters):
            filtered_words.append(word)
    return filtered_words

def interview():
    guess = input("\nEnter your guess: ").strip().upper()
    if len(guess) != 5:
        print("Invalid input. Please enter a 5-letter word.")
        return None, None, None

    green_letters = input("Enter the green letters (correct position): ").strip().upper()
    yellow_letters = input("Enter the yellow letters (wrong position): ").strip().upper()
    bad_letters = input("Enter the bad letters (not in the word): ").strip().upper()

    return guess, green_letters, yellow_letters, bad_letters

def main():
    os.system("cls" if os.name == "nt" else "clear")
    common_words = get_common5()
    uncommon_words = [word.strip() for word in open(word_list, "r").readlines()]

    while True:
        guess, green_letters, yellow_letters, bad_letters = interview()
        if guess is None:
            continue

        filtered_words = run_process(common_words, uncommon_words, green_letters, yellow_letters, bad_letters)
        print_words(filtered_words[:10], filtered_words[10:])

if __name__ == "__main__":
    main()
```

