import os
import yaml
from plugin_system import PluginSystem, verify_package_hook, config_hook

class PuppetState:
    def __init__(self, path):
        self.path = path
        self.data = {}

    def load(self):
        if not os.path.exists(self.path) or not os.path.isfile(self.path):
            return
        with open(self.path, 'r') as f:
            self.data = yaml.safe_load(f)

    def get_checksum(self, file_path):
        for key, value in self.data.items():
            if key.endswith(file_path):
                return value.get('checksums', {}).get('md5')
        return None


class PackageVerifier:
    def __init__(self, puppet_state_file_path=None):
        self.puppet_state = PuppetState(puppet_state_file_path)
        self.plugin_system = PluginSystem()

    def verify_package(self, package_file_path):
