            'package_file_path': package_file_path,
            'checksum': checksum
        }
        self.plugin_system.call_hook('verify_package_hook', verification_data)
        current_checksum = os.popen(f"md5sum {package_file_path}").read().split()[3]
        return current_checksum == verification_data['checksum']


def main():
