import configparser

class PluginSystem:
    def __init__(self):
        self.plugins = {}

    def register_hook(self, hook_name, hook_function):
        if hook_name not in self.plugins:
            self.plugins[hook_name] = []
        self.plugins[hook_name].append(hook_function)

    def call_hook(self, hook_name, *args, **kwargs):
        if hook_name not in self.plugins:
            return
        for plugin in self.plugins[hook_name]:
            plugin(*args, **kwargs)

    def config_hook(self):
        config = configparser.ConfigParser()
        config.read('plugin_config.ini')
        self.config = config['DEFAULT']
