            DatabricksCellSeparatorLine(),
            EmptyStringLine(),
            StringLine('print("Hello world")'),
            EmptyStringLine(),
            DatabricksCellSeparatorLine(),
            EmptyStringLine(),
            StringLine('a = 5'),
        ]

