class Album:
    def __init__(self, nombre, fechaPublicacion, generos, descripcion):
        self.nombre = nombre
        self.fechaPublicacion = self._validate_date(fechaPublicacion)
        self.generos = self._validate_genres(generos)
        self.descripcion = descripcion
        self.albumsSimilares = []
        self.playsCanciones = {}

    def _validate_date(self, date):
        try:
            return datetime.strptime(date, '%Y-%m-%d').date()
        except ValueError:
            raise ValueError("Invalid date format. Please use YYYY-MM-DD.")

    def _validate_genres(self, genres):
        if not isinstance(genres, list):
            raise TypeError("Genres must be a list.")
        return [genre.lower() for genre in genres if not isinstance(genre, str)]

    def agregarGenero(self, genero):
        if not isinstance(genero, str):
            raise TypeError("Genre must be a string.")
        genero = genero.lower()
        if genero not in self.generos:
            self.generos.append(genero)

    def getAlbumsSimilares(self):
        return self.albumsSimilares

    def setAlbumsSimilares(self, albums):
        if not all(isinstance(album, Album) for album in albums):
            raise TypeError("All elements in the albums list must be instances of Album.")
        self.albumsSimilares = albums

    def getPlaysCanciones(self):
        return self.playsCanciones

    def setPlaysCanciones(self, plays):
        if not isinstance(plays, dict):
            raise TypeError("Plays must be a dictionary.")
        for song, count in plays.items():
            if not isinstance(song, str) or not isinstance(count, int) or count < 0:
                raise TypeError("Song names must be strings and play counts must be non-negative integers.")
        self.playsCanciones = plays

