```python
import unittest

class Device:
    def __init__(self, name, initial_state):
        self.name = name
        self.state = initial_state

    def toggle(self):
        if self.state == "AVAILABLE":
            self.state = "UNAVAILABLE"
        elif self.state == "UNAVAILABLE":
            self.state = "AVAILABLE"
        else:
            raise Exception(f"Invalid state: {self.state}")

    def change_state(self, new_state):
        if self.state == "AVAILABLE":
            self.state = new_state
        else:
            raise Exception(f"Cannot change state while unavailable")

    def get_state(self):
        return self.state


class Cover(Device):
    def __init__(self, name, initial_state="CLOSED"):
        super().__init__(name, "AVAILABLE")
        self.initial_state = initial_state

    def open(self):
        if self.state == "AVAILABLE":
            self.state = "OPEN"
        else:
            raise Exception(f"Cannot open while unavailable")

    def close(self):
        if self.state == "AVAILABLE":
            self.state = "CLOSED"
        else:
            raise Exception(f"Cannot close while unavailable")

    def toggle(self):
        if self.state == "OPEN":
            self.close()
        elif self.state == "CLOSED":
            self.open()
        else:
            raise Exception(f"Invalid state: {self.state}")


class Switch(Device):
    def __init__(self, name, initial_state="OFF"):
        super().__init__(name, "AVAILABLE")
        self.initial_state = initial_state

    def turn_on(self):
        if self.state == "AVAILABLE":
            self.state = "ON"
        else:
            raise Exception(f"Cannot turn on while unavailable")

    def turn_off(self):
        if self.state == "AVAILABLE":
            self.state = "OFF"
        else:
            raise Exception(f"Cannot turn off while unavailable")

    def toggle(self):
        if self.state == "ON":
            self.turn_off()
        elif self.state == "OFF":
            self.turn_on()
        else:
            raise Exception(f"Invalid state: {self.state}")


class SmartHomeSystem:
    def __init__(self):
        self.devices = {}

    def add_device(self, device):
        self.devices[device.name] = device

    def remove_device(self, device_name):
        if device_name in self.devices:
            del self.devices[device_name]
        else:
            raise Exception(f"Device not found: {device_name}")

    def get_device(self, device_name):
        if device_name in self.devices:
            return self.devices[device_name]
        else:
            raise Exception(f"Device not found: {device_name}")

    def device_state(self, device_name):
        device = self.get_device(device_name)
        return {
            "name": device.name,
            "state": device.get_state(),
            "type": type(device).__name__
        }


class TestSmartHomeSystem(unittest.TestCase):
    def test_smart_home_system(self):
        system = SmartHomeSystem()

        garage_door = Cover("Garage Door")
        living_room_light = Switch("Living Room Light")

        system.add_device(garage_door)
        system.add_device(living_room_light)

        self.assertEqual(system.device_state("Garage Door"), {
            "name": "Garage Door",
            "state": "AVAILABLE",
            "type": "Cover"
        })

        garage_door.toggle()
        self.assertEqual(system.device_state("Garage Door"), {
            "name": "Garage Door",
            "state": "OPEN",
            "type": "Cover"
        })

        garage_door.change_state("UNAVAILABLE")
        with self.assertRaises(Exception):
            garage_door.toggle()

        living_room_light.turn_on()
        self.assertEqual(system.device_state("Living Room Light"), {
            "name": "Living Room Light",
            "state": "ON",
            "type": "Switch"
        })

        living_room_light.toggle()
        self.assertEqual(system.device_state("Living Room Light"), {
            "name": "Living Room Light",
            "state": "OFF",
            "type": "Switch"
        })

        system.remove_device("Garage Door")
        with self.assertRaises(Exception):
            system.device_state("Garage Door")


if __name__ == "__main__":
    unittest.main()
```

