class TestApp(unittest.TestCase):
    def setUp(self):
        app.config['TESTING'] = True
        self.client = app.test_client()
        db.drop_tables([User])
        db.create_tables([User])

    def tearDown(self):
        db.drop_tables([User])

    def register_user(self, email, password, name, userType):
        user = User.create(
            email=email,
            password=bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()),
            name=name,
            userType=userType
        )
        db.session.commit()
        return user

    def test_login_success(self):
        user = self.register_user('test@example.com', 'password', 'Test User', 'admin')

        response = self.client.post('/login', json={
            'email': 'test@example.com',
            'password': 'password'
        })

        data = json.loads(response.data)

        self.assertEqual(response.status_code, 200)
        self.assertIn('access_token', data)
        self.assertIn('refresh_token', data)
        self.assertIn('user', data)

    def test_login_failure_invalid_email(self):
        self.register_user('test@example.com', 'password', 'Test User', 'admin')

        response = self.client.post('/login', json={
            'email': 'invalid@example.com',
            'password': 'password'
        })

        self.assertEqual(response.status_code, 401)
        self.assertIn('Invalid email or password', json.loads(response.data)['msg'])

    def test_login_failure_invalid_password(self):
        self.register_user('test@example.com', 'password', 'Test User', 'admin')

        response = self.client.post('/login', json={
            'email': 'test@example.com',
            'password': 'invalid_password'
        })

        self.assertEqual(response.status_code, 401)
        self.assertIn('Invalid email or password', json.loads(response.data)['msg'])

    def test_refresh_token_success(self):
        user = self.register_user('test@example.com', 'password', 'Test User', 'admin')
        access_token = create_access_token(identity=user.id)

        response = self.client.post('/auth/refresh', headers={
            'Authorization': f'Bearer {access_token}'
        })

        self.assertEqual(response.status_code, 200)
        self.assertIn('access_token', json.loads(response.data))

if __name__ == '__main__':
    unittest.main()
