import math
import cv2
import matplotlib.pyplot as plt
import numpy as np
import time

def capture_screen():
    try:
        return cv2.imread("screenshot.png")
    except Exception as e:
        print(f"Error while capturing screen: {e}")
        return None

def display_image(image):
    plt.imshow(image)
    plt.title("Game Screen")
    plt.show(block=False)
    plt.pause(0.1)

def get_user_input(image):
    x1, y1 = -1, -1
    x2, y2 = -1, -1

    def on_press(event):
        nonlocal x1, y1, x2, y2
        if x1 == -1:
            x1, y1 = event.xdata, event.ydata
        else:
            x2, y2 = event.xdata, event.ydata

    fig = plt.gcf()
    fig.canvas.mpl_connect('button_press_event', on_press)
    plt.show(block=True)

    if x1 == -1 or x2 == -1:
        print("Invalid input. Please try again.")
        return None

    return (x1, y1), (x2, y2)

def calculate_distance(point1, point2):
    return math.sqrt((point2[0] - point1[0]) ** 2 + (point2[1] - point1[1]) ** 2)

def simulate_tap(duration):
    try:
        cmd = f'adb shell input swipe {point1[0]} {point1[1]} {point2[0]} {point2[1]} {duration}'
        output = subprocess.check_output(cmd, shell=True)
    except Exception as e:
        print(f"Error while simulating tap: {e}")

def main():
    global point1, point2

    while True:
        # Capture the game screen
        image = capture_screen()

        if image is None:
            continue

        # Display the captured image
        display_image(image)

        # Get user input for the starting and ending points of the jump
        input_points = get_user_input(image)

        if input_points is None:
            continue

        point1, point2 = input_points

        # Calculate the Euclidean distance between the two points
        distance = calculate_distance(point1, point2)

        # Simulate a screen tap with a duration proportional to the calculated distance
        simulate_tap(int(distance * 100))

if __name__ == "__main__":
    main()
