```python
import heapq

def top_n_values(d, n):
    if not isinstance(d, dict):
        raise ValueError("The first argument must be a dictionary.")

    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input N must be a positive integer.")

    items = list(d.items())
    max_heap = items[:n]
    heapq.heapify(max_heap)

    for item in items[n:]:
        if item[1] > max_heap[0][1]:
            heapreplace(max_heap, item)

    return sorted(max_heap, key=lambda x: x[1], reverse=True)


