import unittest

class TestTopNValues(unittest.TestCase):
    def test_valid_input(self):
        d = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        result = top_n_values(d, 3)
        self.assertEqual(result, [('item4', 55), ('item1', 45.5), ('item3', 41.3)])

    def test_empty_dictionary(self):
        d = {}
        with self.assertRaises(ValueError):
            top_n_values(d, 3)

    def test_non_integer_n(self):
        d = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        with self.assertRaises(ValueError):
            top_n_values(d, 3.5)

    def test_zero_n(self):
        d = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        with self.assertRaises(ValueError):
            top_n_values(d, 0)

    def test_negative_n(self):
        d = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        with self.assertRaises(ValueError):
            top_n_values(d, -3)

    def test_n_greater_than_items(self):
        d = {'item1': 45.50, 'item2': 35, 'item3': 41.30, 'item4': 55, 'item5': 24}
        result = top_n_values(d, 6)
        self.assertEqual(result, [('item4', 55), ('item1', 45.5), ('item3', 41.3), ('item2', 35), ('item5', 24)])

if __name__ == "__main__":
