Here's a Python class `ConfigMaker` that meets your requirements. It uses the ASE package to create `Atoms` objects.

```python
import numpy as np
from ase import Atoms
from ase.build import fcc111, add_adsorbate
from ase.constraints import FixAtoms

class ConfigMaker:
    def __init__(self):
        self.config_types = self.parse_configtypes()
        self.parse_config()

    def parse_configtypes(self):
        with open('CONFIGTYPES', 'r') as f:
            config_types = [line.strip() for line in f.readlines()]
        return config_types

    def parse_config(self):
        self.lattice_vectors = {}
        self.basis_atoms = {}
        self.box_dimensions = {}
        self.atom_type_mappings = {}

        with open('LATVEC', 'r') as f:
            for line in f.readlines():
                config_type, scale_factor, lat_vec = line.strip().split()
                self.lattice_vectors[config_type] = np.array([float(x) for x in lat_vec.split(',')]) * float(scale_factor)

        with open('BASIS', 'r') as f:
            for line in f.readlines():
                config_type, symbol, position = line.strip().split()
                self.basis_atoms[config_type] = (symbol, np.array([float(x) for x in position.split(',')]))

        with open('BOX', 'r') as f:
            for line in f.readlines():
                config_type, scale_factor, box_dim = line.strip().split()
                self.box_dimensions[config_type] = np.array([float(x) for x in box_dim.split(',')]) * float(scale_factor)

        with open('TYPEMAP', 'r') as f:
            for line in f.readlines():
                atom_type, ase_symbol = line.strip().split()
                self.atom_type_mappings[atom_type] = ase_symbol

    def add(self, symbols, positions, config_type):
        if config_type not in self.config_types:
            raise ValueError(f"Invalid configuration type: {config_type}")

        lattice_vector = self.lattice_vectors[config_type]
        box_dimension = self.box_dimensions[config_type]

        atoms = Atoms(symbols=symbols, positions=positions, cell=lattice_vector, pbc=True)
        atoms.set_constraint(FixAtoms(mask=list(range(len(atoms)))) if box_dimension is None else None)

        if box_dimension is not None:
            atoms.set_cell(box_dimension, scale_atoms=True)

        for i, (atom_type, ase_symbol) in enumerate(self.atom_type_mappings.items()):
            atoms[i].symbol = ase_symbol

        return atoms

    def write_configs(self, filename, format, atoms_list):
        with open(filename, 'w') as f:
            for atoms in atoms_list:
                f.write(f"{format}\n")
                for symbol, position in zip(atoms.get_chemical_symbols(), atoms.get_positions()):
                    f.write(f"{symbol} {','.join(map(str, position))}\n")
                f.write("\n")
```

This class reads the configuration files during initialization and provides methods to add new configurations and write them to a file. The `add` method creates an `Atoms` object using the ASE package and applies the necessary scaling and conversions. The `write_configs` method writes the list of `Atoms` objects to a file in a specified format.

Please note that you need to install the ASE package to use this class. You can install it using pip:

