import os
import multiprocessing
from typing import List, Tuple, Union

def load_dictionary(dictionary_file: str) -> List[str]:
    if not os.path.isfile(dictionary_file):
        raise FileNotFoundError(f"Dictionary file '{dictionary_file}' not found.")

    with open(dictionary_file, 'r') as f:
        words = [word.strip().lower() for word in f.readlines()]

    return words

def gen_acronym(words: List[str], clip: int, dictionary: List[str]) -> List[Tuple[str, List[Tuple[str, int]], str, bool]]:
    acronyms = []
    for word in words:
        word = word.lower()
        clipped_word = word[:clip] if clip > 0 else word
        acronym_letter = clipped_word[0]

        word_components = [(word, words.index(word))]
        processed_acronym = acronym_letter

        if acronym_letter not in (letter[0] for letter in acronyms):
            if acronym_letter in dictionary:
                acronyms.append((acronym_letter, word_components, processed_acronym, True))
            else:
                acronyms.append((acronym_letter, word_components, processed_acronym, False))

    return acronyms
```

