Next, create a function to validate a STAC entry:

```python
import re

UNKNOWN_ID_PREFIX = "UNKNOWN_ID_"
NON_COMMERCIAL_DATASETS = ["your_non_commercial_dataset_id_1", "your_non_commercial_dataset_id_2"]

def is_valid_id(id_field):
    return not id_field.startswith(UNKNOWN_ID_PREFIX)

def validate_stac_entry(stac_entry):
    issues = []

    # ID Check
    if not is_valid_id(stac_entry["id"]):
        issues.append(
            Issue(
                stac_entry,
                f"Invalid 'id' field: starts with '{UNKNOWN_ID_PREFIX}'",
                "error",
            )
        )

    # Type Check
    if stac_entry["type"] not in [member.value for member in StacType]:
        issues.append(
            Issue(
                stac_entry,
                f"Invalid 'type' field: '{stac_entry['type']}' is not a valid STAC type",
                "error",
            )
        )

    # GEE Type Check
    gee_type = stac_entry.get("gee:type", GeeType.NONE.value)
    if gee_type not in [member.value for member in GeeType] and gee_type != GeeType.NONE.value:
        issues.append(
            Issue(
                stac_entry,
                f"Invalid 'gee:type' field: '{gee_type}' is not a valid GEE type",
                "warning",
            )
        )

    # Non-Commercial Check
    dataset_id = stac_entry.get("id", "").split(":")[-1]
    if dataset_id and dataset_id in NON_COMMERCIAL_DATASETS:
        issues.append(
            Issue(
                stac_entry,
                f"Dataset ID '{dataset_id}' is listed as non-commercial",
                "warning",
            )
        )

    return issues
