from django.http import JsonResponse
from django.db import IntegrityError
from .models import Curso, Entregable

def curso(request):
    if request.method == 'POST':
        try:
            nombre = request.POST.get('nombre')
            camada = request.POST.get('camada')

            if not nombre or not camada:
                return JsonResponse({'error': 'Missing required fields: nombre, camada'})

            curso = Curso.objects.create(nombre=nombre, camada=camada)
            curso.save()

            return JsonResponse({'success': True, 'curso': {'nombre': curso.nombre, 'camada': curso.camada}})

        except IntegrityError:
            return JsonResponse({'error': 'Error creating course. A course with the same name and batch number already exists.'})

def entregables(request):
    if request.method == 'POST':
        try:
            nombre = request.POST.get('nombre')
            fechaEntrega = request.POST.get('fechaEntrega')

            if not nombre or not fechaEntrega:
                return JsonResponse({'error': 'Missing required fields: nombre, fechaEntrega'})

            entregable = Entregable.objects.create(nombre=nombre, fechaEntrega=fechaEntrega)
            entregable.save()

            return JsonResponse({'success': True, 'entregable': {'nombre': entregable.nombre, 'fechaEntrega': entregable.fechaEntrega}})

        except IntegrityError:
            return JsonResponse({'error': 'Error creating deliverable. A deliverable with the same name already exists.'})
