    task = TaskModel.query.filter_by(user_id=current_user_id, task_id=task_id).first()
    if task is None:
        return jsonify({"msg": "Task not found"}), 404
    db.session.delete(task)
    db.session.commit()
    return jsonify({"msg": "Task deleted"}), 200

if __name__ == '__main__':
