def create_task(user_id, title, description):
    task_id = str(uuid.uuid4())
    task = {
        'id': task_id,
        'title': title,
        'description': description,
        'completed': False
    }
    users[user_id]['tasks'].append(task)
    tasks[task_id] = user_id
    return task_id

def get_user_tasks(user_id):
    return [task for task in users[user_id]['tasks']]

def modify_task(task_id, title=None, description=None, completed=None):
    if task_id not in tasks:
        return None

    user_id = tasks[task_id]
    task = None
    for i, t in enumerate(users[user_id]['tasks']):
        if t['id'] == task_id:
            task = t
            break

        if not task:
            return None

        if title:
            task['title'] = title
        if description:
            task['description'] = description
        if completed is not None:
            task['completed'] = completed

        users[user_id]['tasks'][i] = task
    return task

def delete_task(task_id):
    if task_id not in tasks:
        return None

    user_id = tasks[task_id]
    for i, t in enumerate(users[user_id]['tasks']):
        if t['id'] == task_id:
            users[user_id]['tasks'].pop(i)
            break

    del tasks[task_id]
    return task_id

@app.route('/api/v2/tasks', methods=['POST'])
@jwt_required
def add_task():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'message': 'Missing title'}), 400

    title = data['title']
    description = data.get('description')

    current_user = get_jwt_identity()
    task_id = create_task(current_user, title, description)
    return jsonify({'task_id': task_id}), 201

@app.route('/api/v2/tasks', methods=['GET'])
@jwt_required
def get_tasks():
    current_user = get_jwt_identity()
    tasks = get_user_tasks(current_user)
    return jsonify([task for task in tasks]), 200

@app.route('/api/v2/tasks/<string:task_id>', methods=['PUT'])
@jwt_required
def update_task(task_id):
    data = request.get_json()
    title = data.get('title')
    description = data.get('description')
    completed = data.get('completed')

    current_user = get_jwt_identity()
    task = modify_task(task_id, title, description, completed)

    if not task:
        return jsonify({'message': 'Task not found'}), 404

    return jsonify(task), 200

@app.route('/api/v2/tasks/<string:task_id>', methods=['DELETE'])
@jwt_required
def delete_task_route(task_id):
    current_user = get_jwt_identity()
    result = delete_task(task_id)

    if not result:
        return jsonify({'message': 'Task not found'}), 404

    return jsonify({'result': 'Task deleted'}), 200
