import argparse
import graphviz
import ast
import sys
from functools import lru_cache

# Command-line argument definitions
parser = argparse.ArgumentParser(description="Generate a dependency graph for a given source file.")
parser.add_argument("source", help="The source file to generate the dependency graph for")
parser.add_argument("-I", "--include-path", action="append", default=[], help="Additional directories to search for included headers")
parser.add_argument("-L", "--library-path", action="append", default=[], help="Directories to search for libraries containing symbols")
parser.add_argument("-o", "--output", default="depgraph.dot", help="Output DOT file name")
parser.add_argument("-x", "--exclude", action="append", default=[], help="Regular expression patterns to exclude certain files")
parser.add_argument("-d", "--depth", type=int, default=10, help="Maximum recursion depth")
parser.add_argument("--forward-declarations", action="store_true", help="Include forward-declared classes in the dependency graph")
parser.add_argument("--find-libraries", action="store_true", help="Attempt to guess which libraries contain the symbols used in the source files")
parser.add_argument("--libraries-only", action="store_true", help="Output only the libraries in the dependency graph, not the individual classes or files")
parser.add_argument("--suppress-unknown-libraries", action="store_true", help="Do not include classes or files in the output if their containing library cannot be determined")

args = parser.parse_args()

# Utility functions
def is_excluded(file_path, exclude_patterns):
    for pattern in exclude_patterns:
        if re.match(pattern, file_path):
            return True
    return False

def get_library_name(symbol, library_paths):
    for library_path in library_paths:
        lib_file = os.path.join(library_path, f"{symbol}.h")
        if os.path.isfile(lib_file):
            return os.path.basename(library_path)
    return None

# Caching decorator for scan_file function
@lru_cache(maxsize=None)
def scan_file_cached(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

# Scanning function
@scan_file_cached
def scan_file(file_path, include_paths, library_paths, depth, forward_declarations, find_libraries, libraries_only, suppress_unknown_libraries):
    dependencies = set()

    if not os.path.isfile(file_path):
        print(f"Error: File '{file_path}' does not exist.")
        return dependencies

    with open(file_path, "r", encoding="utf-8") as f:
        try:
            tree = ast.parse(f.read())
        except SyntaxError as e:
            print(f"Error: Syntax error in file '{file_path}'. {e}")
            return dependencies

    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                if not libraries_only:
                    dependencies.add(alias.name)
                library_name = get_library_name(alias.name, library_paths)
                if library_name and not libraries_only:
                    dependencies.add(library_name)
                elif library_name and libraries_only:
                    dependencies.add(library_name)
                    break

    if depth > 0:
        for header in get_include_headers(file_path, include_paths):
            if not is_excluded(header, args.exclude):
                dependencies.update(scan_file(header, include_paths, library_paths, depth - 1, forward_declarations, find_libraries, libraries_only, suppress_unknown_libraries))

    return dependencies

# Parsing function
def parse_dependencies(dependencies, libraries_only, suppress_unknown_libraries):
    graph = graphviz.Digraph()

    for dependency in dependencies:
        if libraries_only and not dependency.endswith(".h"):
            library_name = get_library_name(dependency, args.library_path)
            if library_name:
                graph.node(library_name)
            else:
                if not suppress_unknown_libraries:
                    graph.node(dependency)
        else:
            graph.node(dependency)

    return graph

# Main function
def main():
    file_dependencies = scan_file(args.source, args.include_path, args.library_path, args.depth, args.forward_declarations, args.find_libraries, args.libraries_only, args.suppress_unknown_libraries)
    graph = parse_dependencies(file_dependencies, args.libraries_only, args.suppress_unknown_libraries)
    graph.render(args.output, view=True)

if __name__ == "__main__":
    main()
