        self.scans = {}

    def register_scan(self, scan_type, file_extensions):
        if isinstance(scan_type, type) and issubclass(scan_type, ScanBase):
            for ext in file_extensions:
                if ext not in self.scans:
                    self.scans[ext] = scan_type
        else:
            raise ValueError("Invalid scan type provided.")

    def execute_scan(self, file_path):
        ext = file_path.split(".")[-1].lower()
        if ext in self.scans:
