import random
import sys

class Gem:
    def __init__(self, color):
        self.color = color
        self.position = None

class Grid:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.grid = [[None for _ in range(width)] for _ in range(height)]

    def is_valid_move(self, pos1, pos2):
        x1, y1 = pos1
        x2, y2 = pos2
        return (x1 == x2 or y1 == y2) and abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def swap_gems(self, gem1, gem2):
        gem1_pos = gem1.position
        gem2_pos = gem2.position
        self.grid[gem1_pos[1]][gem1_pos[0]], self.grid[gem2_pos[1]][gem2_pos[0]] = self.grid[gem2_pos[1]][gem2_pos[0]], self.grid[gem1_pos[1]][gem1_pos[0]]
        gem1.position, gem2.position = gem2.position, gem1.position

    def check_match(self):
        for row in self.grid:
            match_found = self._check_match_in_row(row)
            if match_found:
                return True
        return False

    def _check_match_in_row(self, row):
        for i in range(len(row) - 2):
            if row[i].color == row[i + 1].color and row[i].color == row[i + 2].color:
                return True
        return False

    def reshuffle(self):
        for row in self.grid:
            random.shuffle(row)

class Game:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.grid = Grid(width, height)
        self.score = 0
        self.gems_left = width * height

    def make_move(self, pos1, pos2):
        gem1 = self.grid.grid[pos1[1]][pos1[0]]
        gem2 = self.grid.grid[pos2[1]][pos2[0]]

        if self.grid.is_valid_move(gem1.position, gem2.position):
            self.grid.swap_gems(gem1, gem2)
            match_found = self.grid.check_match()
            if match_found:
