class Solution:
    def sortedInsert(self, s, element):
        if not s or s[-1] <= element:
            s.append(element)
        else:
            top_element = s.pop()
            self.sortedInsert(s, element)
            s.append(top_element)

    def sortStack(self, s):
        if s:
            element = s.pop()
            self.sortStack(s)
            self.sortedInsert(s, element)

    def sorted(self, s):
        self.sortStack(s)
        s.reverse()

