Here's the code for the implementation:

```python
import os
import configparser
from base64 import b64encode, b64decode

class ConfigParserTokenStorage:
    def __init__(self, config_file='tokens.ini'):
        self.config = configparser.ConfigParser()
        self.config_file = config_file

        # Create the configuration file if it doesn't exist
        if not os.path.exists(self.config_file):
            self.config.add_section('client1')
            self.save()

    def save(self, client_id='client1', token=None):
        """Save tokens for a specific client."""
        if token:
            self.config.set(client_id, 'token', b64encode(token.encode()).decode())
        else:
            self.config.set(client_id, 'token', '')
        with open(self.config_file, 'w') as configfile:
            self.config.write(configfile)

    def load(self, client_id='client1'):
        """Load tokens for a specific client."""
        try:
            return b64decode(self.config.get(client_id, 'token')).decode()
        except configparser.NoOptionError:
            return None

    def clear(self, client_id='client1'):
        """Clear tokens for a specific client."""
        self.config.set(client_id, 'token', '')
        with open(self.config_file, 'w') as configfile:
            self.config.write(configfile)

    def clear_all(self):
        """Clear tokens for all clients."""
        self.config.read(self.config_file)
        for section in self.config.sections():
            self.config.remove_section(section)
        with open(self.config_file, 'w') as configfile:
            self.config.write(configfile)


class MultiClientTokenStorage(ConfigParserTokenStorage):
    def __init__(self, config_file='tokens.ini'):
        super().__init__(config_file)

    def save(self, client_id, token):
        """Save tokens for a specific client."""
        if not self.config.has_section(client_id):
            self.config.add_section(client_id)
        super().save(client_id, token)

    def load(self, client_id):
        """Load tokens for a specific client."""
        if self.config.has_section(client_id):
            return super().load(client_id)
        else:
            return None

    def clear(self, client_id):
        """Clear tokens for a specific client."""
        if self.config.has_section(client_id):
            super().clear(client_id)

    def clear_all(self):
        """Clear tokens for all clients."""
        super().clear_all()


# Set appropriate file permissions
os.chmod('tokens.ini', 0o600)  # Only the owner can read and write
```

