from datetime import datetime
from typing import Dict, Any

class Tweets:
    def __init__(self, tweets: Dict[str, Dict[str, Any]]):
        self.tweets = tweets

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Any]]):
        if not all(isinstance(tweet_id, str) for tweet_id in data):
            raise TypeError("Tweet IDs must be strings.")

        tweets = {tweet_id: tweet for tweet_id, tweet in data.items()
                  if isinstance(tweet, dict) and set(tweet.keys()) == {"text", "created_at", "user_id"}}

        for tweet_id, tweet in tweets.items():
            if not isinstance(tweet["text"], str) or not tweet["text"]:
                raise ValueError(f"Invalid or empty text in tweet {tweet_id}.")

            try:
                created_at = datetime.fromisoformat(tweet["created_at"])
            except ValueError:
                raise ValueError(f"Invalid date format in tweet {tweet_id}.")

            tweets[tweet_id] = {"id": tweet_id, "text": tweet["text"], "created_at": created_at, "user_id": tweet["user_id"]}

        return cls(tweets)

    def to_dict(self) -> Dict[str, Dict[str, str]]:
        return {tweet_id: {"text": tweet["text"], "created_at": tweet["created_at"].isoformat(), "user_id": tweet["user_id"]}
                for tweet_id, tweet in self.tweets.items()}

