class Tree:
    def __init__(self):
        self.branches = {}

    def add_branch(self, branch):
        if branch.branch_id in self.branches:
            raise ValueError("Duplicate branch ID")
        self.branches[branch.branch_id] = branch

    def add_leaf(self, branch_id, leaf_value):
        if branch_id not in self.branches:
            raise KeyError(f"Branch ID '{branch_id}' not found")

        branch = self.branches[branch_id]
        if leaf_value is None:
            raise ValueError("Leaf value cannot be None")

        branch.add_child(leaf_value)

    def find_leaf(self, leaf_value):
        for branch in self.branches.values():
            if leaf_value in branch.traverse():
                return branch
        return None

