import json
import torch

def generate_zero_shot_weights(categories_seen, categories_unseen, category_info_path):
    # Load category information from JSON file
    try:
        with open(category_info_path, 'r') as f:
            category_info = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {category_info_path} does not exist.")
    except Exception as e:
        raise Exception(f"Error while loading the file at {category_info_path}: {e}")

    # Create a dictionary of category IDs and their names
    category_ids = {cat['id']: cat['name'] for cat in category_info['categories']}

    # Check if all categories in categories_seen and categories_unseen are valid
    if not set(categories_seen + categories_unseen).issubset(category_ids.keys()):
        raise ValueError("One or more categories in categories_seen or categories_unseen are not valid.")

    # Create a tensor of size 80 with 1.0 for seen categories and 0.0 for unseen categories
    weights = torch.zeros(80)  # assuming 80 categories in total
    for category in categories_seen:
        weights[category - 1] = 1.0  # subtracting 1 because Python uses 0-based indexing

    return weights

