import torch
import torch.nn as nn
import torch.nn.functional as F

class GPP(nn.Module):
    def __init__(self, gpp_type, levels, pool_type='max_pool'):
        super(GPP, self).__init__()

        if gpp_type not in ['spp', 'tpp', 'gpp']:
            raise ValueError("Unknown gpp_type: {}".format(gpp_type))

        self.gpp_type = gpp_type
        self.levels = levels
        self.pool_type = pool_type

        if gpp_type == 'spp' or gpp_type == 'tpp':
            self.pool_layers = nn.ModuleList([nn.AdaptiveMaxPool2d((s, s)) for s in levels])
        elif gpp_type == 'gpp':
            self.pool_layers_h = nn.ModuleList([nn.AdaptiveMaxPool2d((sh, 1)) for sh in levels[0]])
            self.pool_layers_w = nn.ModuleList([nn.AdaptiveMaxPool2d((1, sw)) for sw in levels[1]])

    def _spatial_pyramid_pooling(self, x, mask=None):
        if mask is not None:
            mask = mask.unsqueeze(2).unsqueeze(3)

        pooled_features = []
        for pool_layer in self.pool_layers:
            if mask is not None:
                p = pool_layer(x * mask)
            else:
                p = pool_layer(x)
            pooled_features.append(p.view(p.size(0), -1))

        return torch.cat(pooled_features, dim=1)

    def _temporal_pyramid_pooling(self, x, mask=None):
        if mask is not None:
            mask = mask.unsqueeze(3)

        pooled_features = []
        for pool_layer in self.pool_layers:
            if self.pool_type == 'max_pool':
                p = pool_layer(x * mask)
            elif self.pool_type == 'avg_pool':
                p = F.adaptive_avg_pool2d(x * mask, (p.size(2), p.size(3)))
            else:
                raise ValueError("Unknown pool_type: {}".format(self.pool_type))
            pooled_features.append(p.view(p.size(0), -1))

        return torch.cat(pooled_features, dim=1)

    def _generic_pyramid_pooling(self, x, mask=None):
        if mask is not None:
            mask = mask.unsqueeze(2).unsqueeze(3)

        pooled_features_h = []
        pooled_features_w = []

        for pool_layer_h, pool_layer_w in zip(self.pool_layers_h, self.pool_layers_w):
            p_h = pool_layer_h(x * mask)
            p_w = pool_layer_w(x * mask)

            pooled_features_h.append(p_h.view(p_h.size(0), -1))
            pooled_features_w.append(p_w.view(p_w.size(0), -1))

        return torch.cat(pooled_features_h, dim=1), torch.cat(pooled_features_w, dim=1)

    def forward(self, x, mask=None):
        if self.gpp_type == 'spp':
            return self._spatial_pyramid_pooling(x, mask)
        elif self.gpp_type == 'tpp':
            return self._temporal_pyramid_pooling(x, mask)
        elif self.gpp_type == 'gpp':
            return self._generic_pyramid_pooling(x, mask)
        else:
            raise NotImplementedError("Unknown gpp_type: {}".format(self.gpp_type))

