    def __init__(self):
        self.queue = []

    def enqueue(self, elem):
        self.queue.insert(0, elem)

    def dequeue(self):
        if not self.queue:
            return None
        return self.queue.pop()

    def peek(self, ind=0):
        if ind < 0 or ind >= len(self.queue):
            return None
        return self.queue[ind]

    def clear(self):
        self.queue.clear()

    def size(self):
        return len(self.queue)

