import torch
import copy

class ClassifierFreeSampleModel(torch.nn.Module):
def **init**(self, model, kps\_to\_text\_ratio=1.5):
super(ClassifierFreeSampleModel, self).**init**()
self.model = model
self.kps\_to\_text\_ratio = kps\_to\_text\_ratio

assert hasattr(self.model, 'cond\_mask\_prob'), "Model must be trained with a conditional mask probability greater than zero."
assert self.model.cond\_mask\_prob > 0, "Model must be trained with a conditional mask probability greater than zero."

def forward(self, x, y, cond\_mode='text'):
assert cond\_mode in ['text', 'action'], "Conditional mode must be either 'text' or 'action'."

y\_uncond = copy.deepcopy(y)
if 'uncond' not in y\_uncond:
y\_uncond['uncond'] = True

scale = y\_uncond.get('scale', 1.0)

if cond\_mode == 'text':
x\_cond = self.model(x, **y)
x\_uncond = self.model(x, **y\_uncond)
elif cond\_mode == 'action':
x\_cond = self.model(x, **y)[0]
x\_uncond = self.model(x, **y\_uncond)[0]

return (x\_cond * scale + x\_uncond * (1 - scale)) * self.model.cond\_mask\_prob + x * (1 - self.model.cond\_mask\_prob)

def forward\_smd\_final(self, x, y, cond\_mode='text'):
return self.forward(x, y, cond\_mode) * 1.5

def forward\_correct(self, x, y):
y\_uncond = copy.deepcopy(y)
y\_uncond['uncond'] = True

x\_cond = self.model(x, **y)[0]
x\_uncond = self.model(x, **y\_uncond)[0]

return x\_cond * 1.8 + x\_uncond * (1 - 1.8)

def forward\_average(self, x, y):
y\_uncond = copy.deepcopy(y)
y\_uncond['uncond'] = True

text\_scale = y\_uncond.get('scale', 1.0)
kps\_scale = text\_scale / self.kps\_to\_text\_ratio

x\_text\_cond = self.model(x, **y)[0]
x\_kps\_cond = self.model(x, **y)[1]
x\_uncond = self.model(x, **y\_uncond)[0]

return (x\_text\_cond * text\_scale + x\_kps\_cond * kps\_scale + x\_uncond * (1 - text\_scale - kps\_scale)) * self.model.cond\_mask\_prob + x * (1 - self.model.cond\_mask\_prob)

