```python
import sys

# Board class representing the Quixo board
class Board:
    def __init__(self):
        self.board = [[str(i + j * 5) for i in range(1, 6)] for j in range(5)]
        self.empty_spaces = [(i, j) for i in range(5) for j in range(5) if self.board[i][j] not in ('O', 'X')]

    def display(self):
        print("\n" + "\n---------\n".join("|" + "|".join(row) for row in self.board) + "\n")

    def is_valid_move(self, piece, pos, target):
        i, j = pos
        dx, dy = target

        if self.board[i + dy][j + dx] != piece or (i + dy, j + dx) not in self.empty_spaces:
            return False

        self.board[i + dy][j + dx] = piece
        self.empty_spaces.remove((i + dy, j + dx))
        self.empty_spaces.append((i, j))
        self.board[i][j] = '.'

        return True

    def is_winning_move(self, piece):
        for i in range(5):
            for j in range(5):
                if self.board[i][j] == piece and self.check_line(i, j):
                    return True
        return False

    def check_line(self, x, y):
        # Check rows, columns, and diagonals
        return (all(self.board[x][y] == self.board[x + dx][y + dy] for dx, dy in [(0, 1), (1, 0), (1, 1), (1, -1)]) or
                all(self.board[x][y] == self.board[x + dx][y + dy] for dx, dy in [(0, -1), (1, 0), (1, 1), (1, -1)]) or
                all(self.board[x][y] == self.board[x + dx][y + dy] for dx, dy in [(0, 1), (1, 0), (1, -1), (-1, 0)]]

# Alpha-Beta pruning algorithm for AI move
def alphabeta(board, depth, alpha, beta, maximizing_player):
    if depth == 0 or board.is_winning_move('O') or not board.empty_spaces:
        return evaluate(board)

    if maximizing_player:
        max_eval = float('-inf')
        for pos, target in board.get_possible_moves('O'):
            if board.is_valid_move('O', pos, target):
                board.is_valid_move('O', pos, target)
                eval = alphabeta(board, depth - 1, alpha, beta, False)
                board.is_valid_move('O', target, pos)
                max_eval = max(max_eval, eval)
                alpha = max(alpha, eval)
                if beta <= alpha:
                    break
        return max_eval

    else:
        min_eval = float('inf')
        for pos, target in board.get_possible_moves('X'):
            if board.is_valid_move('X', pos, target):
                board.is_valid_move('X', pos, target)
                eval = alphabeta(board, depth - 1, alpha, beta, True)
                board.is_valid_move('X', target, pos)
                min_eval = min(min_eval, eval)
                beta = min(beta, eval)
                if beta <= alpha:
                    break
        return min_eval

# Evaluate the board state
def evaluate(board):
    if board.is_winning_move('O'):
        return 10
    elif board.is_winning_move('X'):
        return -10
    else:
        return 0

# Get possible moves for a piece
def get_possible_moves(piece, board):
    moves = []
    for i, j in board.empty_spaces:
        if (i - 1, j) in board.empty_spaces and board.board[i - 1][j] == piece:
            moves.append(((i, j), (i - 1, j)))
        if (i + 1, j) in board.empty_spaces and board.board[i + 1][j] == piece:
            moves.append(((i, j), (i + 1, j)))
        if (i, j - 1) in board.empty_spaces and board.board[i][j - 1] == piece:
            moves.append(((i, j), (i, j - 1)))
        if (i, j + 1) in board.empty_spaces and board.board[i][j + 1] == piece:
            moves.append(((i, j), (i, j + 1)))
    return moves

def main():
    board = Board()
    print("Quixo - AI vs Human")
    board.display()

    while True:
        # AI move
        best_score = float('-inf')
        best_move = None

        for pos, target in board.get_possible_moves('O'):
            if board.is_valid_move('O', pos, target):
                board.is_valid_move('O', pos, target)
                score = alphabeta(board, 3, float('-inf'), float('inf'), False)
                board.is_valid_move('O', target, pos)

                if score > best_score:
                    best_score = score
                    best_move = (pos, target)

        board.is_valid_move('O', best_move[0], best_move[1])
        print("AI moves piece", best_move[0], "to", best_move[1])
        board.display()

        if board.is_winning_move('O'):
            print("AI wins!")
            sys.exit(0)

        # Human move
        while True:
            try:
                human_move = tuple(map(int, input("Enter your move (piece position and target position separated by a space): ").split()))
                if len(human_move) != 2 or human_move[0] < 1 or human_move[0] > 25 or human_move[1] < 1 or human_move[1] > 25:
                    raise ValueError
                break
            except ValueError:
                print("Invalid input. Please enter two numbers separated by a space.")

        piece, target = human_move
        pos = (piece - 1) // 5, (piece - 1) % 5

        if board.is_valid_move('X', pos, target):
            board.is_valid_move('X', pos, target)
            if board.is_winning_move('X'):
                print("Human wins!")
                sys.exit(0)
            board.display()
        else:
            print("Invalid move. Please try again.")

if __name__ == "__main__":
    main()
```

