import numpy as np

def input_positive_integer():
    while True:
        try:
            n = int(input("Enter a positive integer: "))
            if n > 0:
                return n
            else:
                print("Please enter a number greater than 0.")
        except ValueError:
            print("Invalid input. Please enter a positive integer.")

def create_circular_adjacency_matrix(n):
    A = np.full((n, n), 3)
    for i in range(n - 1):
        A[i, i + 1] = A[i + 1, i] = -1
    A[0, -1] = A[-1, 0] = -1
    return A

def gaussian_elimination(A):
    n = A.shape[0]
    for i in range(n - 1):
        for j in range(i + 1, n):
            factor = A[j, i] / A[i, i]
            A[j, i:] -= factor * A[i, i:]
    return A

def calculate_determinant(A):
    return np.linalg.det(A)

def main():
    n = input_positive_integer()
    A = create_circular_adjacency_matrix(n)
    U = gaussian_elimination(A)
    det = calculate_determinant(U)
    print(f"The determinant of the circular adjacency matrix is: {int(det)}")

if __name__ == "__main__":
    main()
