```python
import json
import re

import requests
from bs4 import BeautifulSoup


def scrape_airfield_data(url):
    response = requests.get(url)
    html_content = response.text
    soup = BeautifulSoup(html_content, "html.parser")

    airfields_data = []

    airfield_table = soup.find("table", {"class": "wikitable"})
    airfield_rows = airfield_table.find_all("tr")

    for row in airfield_rows[1:]:
        cols = row.find_all("td")
        if len(cols) >= 13:
            airfield_data = {
                "code": cols[0].text.strip(),
                "name": cols[1].text.strip(),
                "magnetic_orientation": cols[2].text.strip(),
                "latitude": cols[3].text.strip(),
                "longitude": cols[4].text.strip(),
                "altitude": _parse_altitude(cols[5].text.strip()),
                "traffic": cols[6].text.strip(),
                "ground_level": _parse_altitude(cols[7].text.strip()),
                "status": cols[8].text.strip().capitalize(),
                "runways": [],
            }

            runway_cols = cols[9:]
            for rc in runway_cols[::2]:
                surface_col = runway_cols[runway_cols.index(rc) + 1]
                airfield_data["runways"].append(
                    {
                        "orientation": _parse_orientation(rc.text.strip()),
                        "threshold_positions": _parse_threshold_positions(rc.text.strip()),
                        "altitudes": _parse_altitudes(rc.text.strip()),
                        "surface_type": _parse_surface_type(surface_col.text.strip()),
                    }
                )

            airfields_data.append(airfield_data)

    return airfields_data


def _parse_altitude(altitude_str):
    if re.match(r"^\d+$", altitude_str):
        return int(altitude_str)
    elif re.match(r"^\d+\.\d+$", altitude_str):
        return float(altitude_str)
    else:
        return None


def _parse_orientation(orientation_str):
    match = re.match(r"(\d{3})(E|W)$", orientation_str)
    if match:
        direction = "E" if match.group(2) == "E" else "W"
        return int(match.group(1)) if direction == "E" else -int(match.group(1))
    else:
        return None


def _parse_threshold_positions(threshold_positions_str):
    match = re.match(r"(\d+)/(\d+)$", threshold_positions_str)
    if match:
        return (int(match.group(1)), int(match.group(2)))
    else:
        return None


def _parse_altitudes(altitude_str):
    match = re.search(r"\((\d+)ft\)", altitude_str)
    if match:
        return int(match.group(1))
    else:
        return None


def _parse_surface_type(surface_type_str):
    if re.match(r"Asphalt", surface_type_str):
        return {"length": None, "width": None, "type": "asphalt"}
    elif re.match(r"Concrete", surface_type_str):
        return {"length": None, "width": None, "type": "concrete"}
    elif re.match(r"\d+/\d+", surface_type_str):
        length, width = map(int, re.findall(r"\d+", surface_type_str))
        return {"length": length, "width": width, "type": None}
    else:
        return None


if __name__ == "__main__":
    url = "https://en.wikipedia.org/wiki/List_of_airports_in_the_United_Kingdom_by_type_and_location"
    airfields_data = scrape_airfield_data(url)

    with open("airfields_data.json", "w") as f:
        json.dump(airfields_data, f, indent=2)
```

This script will scrape airfield data from the specified URL and save it in a JSON file called `airfields_data.json`. The data will be structured as described in the prompt.

