import math

class CacheItem:
    def __init__(self, key=None, value=None, expiration=None):
        self.key = key
        self.value = value
        self.expiration = expiration

    def get_key(self):
        return self.key

    def get(self):
        if self.is_expired():
            return None
        return self.value

    def is_hit(self):
        if self.key is None or self.value is None:
            return False
        return not self.is_expired()

    def set(self, key, value):
        self.key = key
        self.value = value
        self.expiration = None

    def is_expired(self):
        if self.expiration is None:
            return False
        return datetime.now() > self.expiration

    def expires_at(self, timestamp):
        if not isinstance(timestamp, datetime):
            raise ValueError("Expiry time must be a datetime object")
        self.expiration = timestamp

    def expires_after(self, seconds):
        if not isinstance(seconds, (int, float)):
            raise ValueError("Expiry time must be a numeric value")
        self.expiration = datetime.now() + timedelta(seconds=seconds)


class InMemoryCache:
    def __init__(self):
        self.cache = {}

    def get_item(self, key):
        if key not in self.cache:
            return None
        return self.cache[key]

    def set_item(self, key, value):
        cache_item = CacheItem(key, value)
        self.cache[key] = cache_item

    def has_key(self, key):
        return key in self.cache

    def delete_item(self, key):
        if key in self.cache:
            del self.cache[key]

    def clear(self):
