```python
import os
import shutil
import re
from lxml import etree

# Parse EAD files and create a list of call numbers and collection IDs
def parse_ead_files(ead_dir):
    call_numbers_and_ids = []
    namespaces = {'ead': 'http://www.loc.gov/ead/2002'}

    for filename in os.listdir(ead_dir):
        if filename.endswith('.xml'):
            ead_file = os.path.join(ead_dir, filename)
            tree = etree.parse(ead_file)
            root = tree.getroot()

            try:
                unitid = root.find('.//ead:unitid', namespaces).text
                eadid = root.find('.//ead:eadid', namespaces).text
                call_numbers_and_ids.append((unitid, eadid))
            except Exception as e:
                print(f"Error parsing EAD file {filename}: {e}")

    return call_numbers_and_ids

# Parse MARC records and check for the presence of an EAD link or a call number
def parse_marc_records(marc_dir, call_numbers_and_ids):
    ead_links_dir = os.path.join(marc_dir, 'with_ead_links')
    call_numbers_dir = os.path.join(marc_dir, 'with_call_numbers')
    neither_dir = os.path.join(marc_dir, 'neither')

    os.makedirs(ead_links_dir, exist_ok=True)
    os.makedirs(call_numbers_dir, exist_ok=True)
    os.makedirs(neither_dir, exist_ok=True)

    for filename in os.listdir(marc_dir):
        if filename.endswith('.xml'):
            marc_file = os.path.join(marc_dir, filename)
            tree = etree.parse(marc_file)
            root = tree.getroot()

            ead_link = None
            call_number = None

            for datafield in root.findall('.//datafield'):
                if datafield.get('tag') == '856':
                    for subfield in datafield.findall('.//subfield'):
                        if subfield.get('code') == 'u':
                            ead_link = subfield.text
                elif datafield.get('tag') == '852':
                    for subfield in datafield.findall('.//subfield'):
                        if subfield.get('code') == 'h':
                            call_number = subfield.text

            if ead_link and call_number:
                for call_number_id in call_numbers_and_ids:
                    if re.search(call_number_id[0], call_number):
                        shutil.copy(marc_file, os.path.join(ead_links_dir, filename))
                        break
            elif call_number and not ead_link:
                shutil.copy(marc_file, os.path.join(call_numbers_dir, filename))
            elif not call_number and not ead_link:
                shutil.copy(marc_file, os.path.join(neither_dir, filename))
            else:
                print(f"Error processing MARC file {filename}")

# Unit tests
def test_parse_ead_files():
    ead_dir = 'test_data/ead'
    call_numbers_and_ids = parse_ead_files(ead_dir)
    assert len(call_numbers_and_ids) == 2
    assert call_numbers_and_ids[0] == ('A1', 'collection1')
    assert call_numbers_and_ids[1] == ('B2', 'collection2')

def test_parse_marc_records():
    marc_dir = 'test_data/marc'
    parse_marc_records(marc_dir, parse_ead_files('test_data/ead'))

    assert os.listdir('test_data/marc/with_ead_links') == ['file1.xml']
    assert os.listdir('test_data/marc/with_call_numbers') == ['file3.xml']
    assert os.listdir('test_data/marc/neither') == ['file2.xml']

if __name__ == '__main__':
    ead_dir = 'path/to/ead'
    marc_dir = 'path/to/marc'

    if os.path.exists(ead_dir) and os.path.exists(marc_dir):
        call_numbers_and_ids = parse_ead_files(ead_dir)
        parse_marc_records(marc_dir, call_numbers_and_ids)
    else:
        print("Source directories not found.")
```

Replace `'path/to/ead'` and `'path/to/marc'` with the actual paths to your EAD and MARC directories. The script will create three directories inside the MARC directory: `with_ead_links`, `with_call_numbers`, and `neither`. MARC files will be copied into the appropriate directory based on the presence of an EAD link or a call number.

The unit tests are located at the bottom of the script. You can run them to ensure that the EAD and MARC parsing functions are working correctly.

