from django.urls import path, include

def generate_urlpatterns(pages, app_name):
    urlpatterns = []

    for page, view_func in pages:
        if page == 'admin':
            urlpatterns.append(path('', include(admin.site.urls)))
        else:
            urlpatterns.append(path(page, view_func, name=page))

    handler404 = next((view_func for page, view_func in pages if page == '404'), None)
    handler500 = next((view_func for page, view_func in pages if page == '500'), None)

    if handler404:
        urlpatterns.append(path('404/', handler404, name='404'))
    if handler500:
        urlpatterns.append(path('500/', handler500, name='500'))

    return urlpatterns
